/*
 * Cross-compile determinism of M8 specialization. A concrete, typed function's
 * body must specialize to the SAME native/typed bytecode no matter what was
 * compiled BEFORE it in the same process - in particular, compiling an
 * untyped-parameter TEMPLATE (which instantiates a `name$N` clone) must not
 * leak state into the next one-shot compile's infer_types / specialize_types.
 *
 * The one-shot infer_types uses a FRESH local Inferencer per call (all_syms /
 * all_funcs / tmpl_cache / clone_name_counter / id_sym / the type arena are
 * per-instance) and specialize_types clears its file-scope state (g_fr_pure)
 * each call, so no compile-time state crosses compiles - this pins that
 * invariant. It caught nothing at the time it was written (the property already
 * holds), but a regression that added persistent inferencer/specializer state
 * would make the typed function come out BOXED (BinOpV) after a template - the
 * exact shape this asserts against. See MEMORY
 * [[template-compile-pollutes-next-specialization]].
 */
/* Compile+run a whole program in one process under the VM engine. If `fname`
 * is non-null it must be a CONCRETE function whose compiled chunk + M8 signal
 * are captured; a null `fname` just compiles+runs (used for the polluter, whose
 * only interesting function is a template base with no chunk of its own). */
static bool ccs_compile(const std::vector<const char *> &lines,
                        const char *fname, std::vector<int> &ops,
                        int &typed, int &multiop, int &binopv, bool &is_tmpl)
{
    std::string src;
    std::vector<Tok> toks;
    for (size_t i = 0; i < lines.size(); i++) {
        if (i) src += '\n';
        src += lines[i];
    }
    lexer(src, 1, toks);
    const ExecEngine saved = g_exec_engine;
    g_exec_engine = ExecEngine::Vm;
    bool ok = true;
    try {
        ParseContext pc(TokenStream(toks), true);
        unique_ptr<Construct> root = pBlock(pc);
        mark_implicit_globals(root.get(), {});
        infer_types(root.get(), true);
        run_optimizers(root.get());
        Block *b = dynamic_cast<Block *>(root.get());
        if (fname) {
            FuncDeclStmt *fd = nullptr;
            if (b)
                for (auto &e : b->elems)
                    if (auto *f = dynamic_cast<FuncDeclStmt *>(e.get()))
                        if (f->id && f->id->get_str() == fname) { fd = f; break; }
            if (!fd) { g_exec_engine = saved; return false; }
            is_tmpl = fd->is_template;
            /* The M8 signal on the AST (JIT-independent): a fully specialized
             * body has only TypedScalarExpr arith, no boxed MultiOpConstruct. */
            std::function<void(Construct *)> walk = [&](Construct *n) {
                if (!n) return;
                if (dynamic_cast<TypedScalarExpr *>(n)) typed++;
                if (dynamic_cast<MultiOpConstruct *>(n)) multiop++;
                for_each_child_of(n, walk);
            };
            if (fd->body) walk(fd->body.get());
            Chunk ch;
            if (!codegen_func_body(fd, ch)) { g_exec_engine = saved; return false; }
            for (const Instr &in : ch.code) {
                ops.push_back((int)in.op);
                if (in.op == OpCode::BinOpV) binopv++;
            }
        }
/* Run it end-to-end (matches the driver: infer -> optimize -> run). */
        vm_execute(root.get());
    } catch (...) {
        ok = false;
    }
    g_exec_engine = saved;
    return ok;
}
static bool cross_compile_specialize_stable()
{
    /* B: a concrete, fully-typed function whose four int arith ops must all
     * specialize (4 TypedScalarExpr, no boxed BinOpV). Used with sort so the
     * callback path is exercised. */
    const std::vector<const char *> B = {
        "func cmp(int a, int b) {",
        "  var d = a * 3; var e = b * 5; var f = d - e; return f + a;",
        "}",
        "var arr = [5, 2, 8, 1, 9, 3, 7, 4, 6, 0];",
        "sort(arr, cmp);" };
    /* A: an untyped-parameter TEMPLATE (instantiated as leaf$0), the historic
     * suspected polluter. */
    const std::vector<const char *> A = {
        "func leaf(a, b) { var t = a * b; var u = t + a; return u - b; }",
        "var acc = 0;",
        "for (var i = 1; i <= 3; i++) acc = acc + leaf(i, 2);" };

    std::vector<int> ops_iso, ops_after, junk;
    int t_iso = 0, m_iso = 0, bv_iso = 0;
    int t_after = 0, m_after = 0, bv_after = 0;
    int jt = 0, jm = 0, jb = 0;
    bool tmpl_iso = false, tmpl_after = false, jtm = false;

    /* cmp in isolation, then the template polluter, then cmp again. */
    if (!ccs_compile(B, "cmp", ops_iso, t_iso, m_iso, bv_iso, tmpl_iso))
        return false;
    if (!ccs_compile(A, nullptr, junk, jt, jm, jb, jtm))
        return false;
    if (!ccs_compile(B, "cmp", ops_after, t_after, m_after, bv_after,
                     tmpl_after))
        return false;

    /* cmp is concrete, never a template; its 4 arith ops all specialize; no
     * boxed BinOpV - in BOTH compiles. */
    if (tmpl_iso || tmpl_after) return false;
    if (t_iso != 4 || t_after != 4) return false;
    if (m_iso != 0 || m_after != 0) return false;
    if (bv_iso != 0 || bv_after != 0) return false;
    /* And byte-identical bytecode: a template compile changed NOTHING. */
    if (ops_iso != ops_after) return false;
    return true;
}

/* #55 STEP 2.1: a native_leaf callee called from ANOTHER function issues a
 * NATIVE call (jit_call_setup) from the caller's fragment instead of an
 * interpreted CallV. PROVE the native call ran (g_jit_native_calls bumps) with
 * a correct result. runtime() keeps the arg non-const so the callee is not
 * specialized to a clone (a const arg -> nleaf$0, a not-yet-native case). */
static bool jit_native_call()
{
#if ML_JIT_SUPPORTED
    if (!g_jit_enabled)
        return true;
    auto run = [](const std::vector<const char *> &lines) -> bool {
        std::string src;
        std::vector<Tok> toks;
        for (size_t i = 0; i < lines.size(); i++) {
            if (i) src += '\n';
            src += lines[i];
        }
        lexer(src, 1, toks);
        const ExecEngine saved = g_exec_engine;
        g_exec_engine = ExecEngine::Vm;
        bool ok = true;
        try {
            ParseContext pc(TokenStream(toks), true);
            unique_ptr<Construct> root = pBlock(pc);
            mark_implicit_globals(root.get(), {});
            infer_types(root.get(), true);
            run_optimizers(root.get());
            vm_execute(root.get());
        } catch (...) {
            ok = false;
        }
        g_exec_engine = saved;
        return ok;
    };

    const unsigned long b0 = g_jit_native_calls;
    if (!run({ "func nleaf(int a, int b) {",
               "  var t = a * b;",
               "  var u = t + a;",
               "  var v = u - b;",
               "  var w = v * a;",
               "  var x = w + b;",
               "  return x - a;",
               "}",
               "func ncaller(int n) {",
               "  var acc = 0;",
               "  for (var i = 1; i <= n; i++) acc = acc + nleaf(i, n);",
               "  return acc;",
               "}",
               "assert(ncaller(runtime(50)) == 2126650);" }))
        return false;
    if (g_jit_native_calls <= b0)
        return false;   /* the native call did NOT run - a silent regression */
    return true;
#else
    return true;
#endif
}

/*
 * The fragment-inline sync push binds a REFERENCE argument (an array, string,
 * dict or struct) instead of declining the whole push to the C++ slow tier.
 * That decline used to fire on EVERY call passing a container - most real code
 * - and cost 55% of 76_funcval_dispatch's instructions.
 *
 * PROVE the native path served it: g_jit_ref_arg_binds is bumped only by
 * jit_bind_ref_arg, which only the EMITTED push calls. A result check alone
 * would pass with the old decline, since the slow tier computes the same
 * answer - the whole point is WHICH path ran.
 *
 * The SLICE case is the reason the bind is a call and not an inlined refcount
 * bump: a slice registers itself in its parent's `slices` set on copy, so a
 * raw payload copy plus a retain would corrupt that set. It is exercised here
 * and its result checked against the un-jitted engine's.
 */
static bool jit_ref_arg_bind()
{
#if ML_JIT_SUPPORTED
    if (!g_jit_enabled)
        return true;
    auto run = [](const std::vector<const char *> &lines) -> bool {
        std::string src;
        std::vector<Tok> toks;
        for (size_t i = 0; i < lines.size(); i++) {
            if (i) src += '\n';
            src += lines[i];
        }
        lexer(src, 1, toks);
        const ExecEngine saved = g_exec_engine;
        g_exec_engine = ExecEngine::Vm;
        bool ok = true;
        try {
            ParseContext pc(TokenStream(toks), true);
            unique_ptr<Construct> root = pBlock(pc);
            mark_implicit_globals(root.get(), {});
            infer_types(root.get(), true);
            run_optimizers(root.get());
            vm_execute(root.get());
        } catch (...) {
            ok = false;
        }
        g_exec_engine = saved;
        return ok;
    };

    /* An ARRAY argument through a DIRECT call. The body is deliberately
     * several statements: a small one is INLINED away by the optimizer, so
     * there is no call left to bind - which is how the first version of this
     * test managed to exercise nothing. */
    unsigned long b0 = g_jit_ref_arg_binds;
    if (!run({ "func addto(a, x) {",
               "  var t = a[0] + x;",
               "  var u = t * 2;",
               "  var v = u - t;",
               "  a[0] = v;",
               "  return v;",
               "}",
               "var st = [0];",
               "for (var i = 0; i < 40; i++) addto(st, i);",
               "assert(st[0] == 780);" }))
        return false;
    if (g_jit_ref_arg_binds <= b0)
        return false;         /* the inline push still DECLINED the call */

    /* a STRING argument, and an indirect call through a func value */
    b0 = g_jit_ref_arg_binds;
    if (!run({ "func f1(s, k) { return len(s) + k; }",
               "func f2(s, k) { return len(s) - k; }",
               "var ops = [f1, f2];",
               "var acc = 0;",
               "for (var i = 0; i < 40; i++) {",
               "  var fn = ops[i % 2];",
               "  acc = acc + fn(\"abcde\", i);",
               "}",
               "assert(acc == 180);" }))
        return false;
    if (g_jit_ref_arg_binds <= b0)
        return false;

    /* a SLICE argument: the copy must register the new view in the parent's
     * slices set, which only the real C++ copy does. Mutating the base while
     * views are live is what makes a corrupted set observable. */
    b0 = g_jit_ref_arg_binds;
    if (!run({ "func first(a, k) {",
               "  var t = a[0] + k;",
               "  var u = t * 3 - k;",
               "  var v = u - t - t;",
               "  return t + v - v;",
               "}",
               "var base = [10, 20, 30, 40, 50];",
               "var s = 0;",
               "for (var i = 0; i < 20; i++) {",
               "  var sl = base[1:4];",
               "  s += first(sl, i);",
               "  base[1] = base[1] + 1;",
               "}",
               "assert(s == 190 + 590);",
               "assert(base[1] == 40);" }))
        return false;
    if (g_jit_ref_arg_binds <= b0)
        return false;
    return true;
#else
    return true;
#endif
}

/* model-flip M3 (plans/model-flip.md): a straight-line boxed LEAF compiles to a
 * native CONTAINER - one EnterNative drives the body, the boxed ISLAND is a
 * `call jit_exec_block`, the ReturnV is native. PROVE it ran (g_jit_container_
 * calls bumps, the "prove the code ran" rule) with a correct result, AND that a
 * throw propagates + is catchable. dyn params keep the body boxed; the block
 * body keeps it above the inline threshold (so it stays a real call, not inlined
 * away). The ISLAND op is a `const` ARRAY DECL (DeclConstV) - as the
 * nativize-ops path made BinOpV/CmpV/CompoundV/MoveV/LogV/UnaryV/CoerceNumV,
 * SliceV, MakeArrayV, MakeDictV and the struct builds all NATIVE, DeclConstV is
 * the container gate's remaining still-boxed island source (the source hops to
 * the next still-boxed simple op each time one is nativized). A straight-line
 * container needs total island ops >= MIN_CONTAINER_ISLAND, so subtest (1)
 * chains 6 const decls (each its own 1-op island; total 6 >= 5). */
static bool jit_container()
{
#if ML_JIT_SUPPORTED
    if (!g_jit_enabled)
        return true;
    auto run = [](const std::vector<const char *> &lines) -> bool {
        std::string src;
        std::vector<Tok> toks;
        for (size_t i = 0; i < lines.size(); i++) {
            if (i) src += '\n';
            src += lines[i];
        }
        lexer(src, 1, toks);
        const ExecEngine saved = g_exec_engine;
        g_exec_engine = ExecEngine::Vm;
        bool ok = true;
        try {
            ParseContext pc(TokenStream(toks), true);
            unique_ptr<Construct> root = pBlock(pc);
            mark_implicit_globals(root.get(), {});
            infer_types(root.get(), true);
            run_optimizers(root.get());
            vm_execute(root.get());
        } catch (...) {
            ok = false;
        }
        g_exec_engine = saved;
        return ok;
    };

    /* THE ISLAND-SOURCE HOP CHAIN IS EXHAUSTED (2026-07-25): with the
     * dyn-callee pair (CheckCallableV/CallValueGenericV) nativized, NO
     * sequential op remains that op_is_simple_island admits but
     * op_run_eligible rejects - so jit_try_container can no longer form a
     * container from real code, and these former container shapes now
     * compile FULLY NATIVE. The g_jit_container_calls assertions are
     * therefore retired; the vm_exec_block machinery (M2) stays covered by
     * the synthetic vm_exec_block_selftest, and the container path remains
     * in place for future un-nativizable ops. These cases stay as
     * correctness pins for the shapes themselves.
     *
     * (1) discarded DYN-callee calls (formerly the island source); their array args compile to ELIGIBLE ops, so the islands
     * are the check+call pairs. Returns the arg. runtime() keeps the call
     * non-const so the pure call isn't folded away (else cleaf never runs
     * -> no container). */
    if (!run({ "func cleaf(dyn a) {",
               "  var dyn f = len;",
               "  f([1, 2]);",
               "  f([3, 4]);",
               "  f([5, 6]);",
               "  f([7, 8]);",
               "  return a;",
               "}",
               "assert(cleaf(runtime(\"hello\")) == \"hello\");" }))
        return false;
    /* (2) a JIT-thrown div-by-zero (native BinOpV `x / b` -> jit_boxed_binop
     * catches div0 -> g_vm_jit_exc -> EnterNative re-raises) is catchable. */
    if (!run({ "func cx(dyn a, dyn b) {",
               "  var dyn t = a + b; var dyn u = t + a; var dyn v = u + b;",
               "  var dyn w = v + a; var dyn x = w + b;",
               "  return x / b;",
               "}",
               "var caught = false;",
               "try { var dyn z = cx(runtime(1), 0); }",
               "catch (DivisionByZeroEx) { caught = true; }",
               "assert(caught);" }))
        return false;
    /* (3) a native LOOP whose body holds a dyn call - formerly a container
     * with a per-iteration island, now fully native end to end. */
    if (!run({ "func lc(dyn a, int n) {",
               "  var dyn last = a;",
               "  var dyn f = len;",
               "  for (var i = 0; i < n; i++) {",
               "    f([1, 2]);",
               "    var j = i + 1;",
               "  }",
               "  return last;",
               "}",
               "assert(lc(runtime(\"hello\"), 5) == \"hello\");" }))
        return false;
    /* (4) MULTIPLE fragments/regions in one body - an init `[a]` and a body
     * `[a]` (MakeArrayV, native since the nativize-ops pass; kept as a
     * correctness shape - no island assertion). */
    if (!run({ "func lc2(dyn a, int n) {",
               "  var dyn s = [a];",
               "  for (var i = 0; i < n; i++) {",
               "    s = [a];",
               "    var j = i + 1;",
               "  }",
               "  return s;",
               "}",
               "assert(lc2(runtime(\"hello\"), 5)[0] == \"hello\");" }))
        return false;
    return true;
#else
    return true;
#endif
}

/* model-flip (nativize-ops): PROVE EACH nativized op's native code actually
 * RUNS (the "prove the code ran" rule per-op - a differential pass only proves
 * the RESULT is right, which the interpreter could produce; this proves the
 * NATIVE path executed). Per op: run a loop that exercises it, assert the
 * result (an `assert` in the program) AND that its per-op counter g_jit_op_run[
 * op] bumped (so the op landed in a fragment and its jit_* helper was called).
 * If a counter fails to bump, the op is nativized but NOT actually emitted/run
 * in that shape - a real gap this test surfaces. */
/* Re-raise deletability (plans/model-flip.md): a native_leaf must be
 * EXIT-FREE (op_never_exits), because the #55 direct call IGNORES the callee
 * fragment's return value. Pre-fix, a non-inlined `len(dyn)` leaf's
 * CallBuiltinV conveyed its throw, the direct caller dropped it (stale dst,
 * callee frame left pushed) and the program HUNG. Inlining is disabled so
 * the callee stays a real call (the `-ni` shape that found it); the fixed
 * gate routes it through the sync path, which handles the throw. */
static bool jit_leaf_never_exits()
{
#if ML_JIT_SUPPORTED
    if (!g_jit_enabled)
        return true;
    std::string src;
    std::vector<Tok> toks;
    for (const char *l : {
            "func lf(dyn x) => len(x);",
            "func caller(int n) {",
            "  var s = 0;",
            "  for (var i = 0; i < n; i++) {",
            "    try { s += lf(runtime(5)); } catch (TypeErrorEx) { s += 1; }",
            "  }",
            "  return s;",
            "}",
            "assert(caller(runtime(3)) == 3);" }) {
        if (!src.empty())
            src += '\n';
        src += l;
    }
    lexer(src, 1, toks);
    const ExecEngine saved = g_exec_engine;
    g_exec_engine = ExecEngine::Vm;
    bool ok = true;
    try {
        ParseContext pc(TokenStream(toks), true);
        unique_ptr<Construct> root = pBlock(pc);
        mark_implicit_globals(root.get(), {});
        infer_types(root.get(), true);
        run_optimizers(root.get(), /*enable_inline=*/false);
        vm_execute(root.get());
    } catch (...) {
        ok = false;
    }
    g_exec_engine = saved;
    return ok;
#else
    return true;
#endif
}

static bool jit_op_nativized()
{
#if ML_JIT_SUPPORTED
    if (!g_jit_enabled)
        return true;
    auto run = [](const std::vector<const char *> &lines) -> bool {
        std::string src;
        std::vector<Tok> toks;
        for (size_t i = 0; i < lines.size(); i++) {
            if (i) src += '\n';
            src += lines[i];
        }
        lexer(src, 1, toks);
        const ExecEngine saved = g_exec_engine;
        g_exec_engine = ExecEngine::Vm;
        bool ok = true;
        try {
            ParseContext pc(TokenStream(toks), true);
            unique_ptr<Construct> root = pBlock(pc);
            mark_implicit_globals(root.get(), {});
            infer_types(root.get(), true);
            run_optimizers(root.get());
            vm_execute(root.get());
        } catch (...) {
            ok = false;
        }
        g_exec_engine = saved;
        return ok;
    };
    struct Case { OpCode op; std::vector<const char *> src; };
    const std::vector<Case> cases = {
        /* MoveV: two dyn slot copies in the loop body. */
        { OpCode::MoveV, {
            "func f(dyn a, int n) {",
            "  var dyn s = 0;",
            "  for (var i = 0; i < n; i++) { var dyn t = a; s = t; }",
            "  return s;",
            "}",
            "assert(f(runtime(42), 5) == 42);" } },
        /* SubscriptV: a general (dyn-base) subscript per iteration. */
        { OpCode::SubscriptV, {
            "func f(dyn a, int n) {",
            "  var dyn s = 0;",
            "  for (var i = 0; i < n; i++) s = s + a[i];",
            "  return s;",
            "}",
            "assert(f(runtime([10, 20, 30, 40, 50]), 5) == 150);" } },
        /* MemberV: a general (dyn-base) member read per iteration. */
        { OpCode::MemberV, {
            "struct P { int x; }",
            "func f(dyn p, int n) {",
            "  var dyn s = 0;",
            "  for (var i = 0; i < n; i++) s = s + p.x;",
            "  return s;",
            "}",
            "assert(f(runtime(P(7)), 5) == 35);" } },
        /* LoadConstV: a const-pool value materialized per iteration. */
        { OpCode::LoadConstV, {
            "func f(int n) {",
            "  var dyn s = 0;",
            "  for (var i = 0; i < n; i++) { var dyn c = \"ab\"; s = c; }",
            "  return len(s);",
            "}",
            "assert(f(runtime(5)) == 2);" } },
        /* LoadBuiltinV: a builtin loaded as a value per iteration. */
        { OpCode::LoadBuiltinV, {
            "func f(dyn a, int n) {",
            "  var dyn r = 0;",
            "  for (var i = 0; i < n; i++) { var dyn g = len; r = g(a); }",
            "  return r;",
            "}",
            "assert(f(runtime([1, 2, 3]), 5) == 3);" } },
        /* StoreGlobalV: a plain global store per iteration. */
        { OpCode::StoreGlobalV, {
            "var gg = 0;",
            "func f(int n) { for (var i = 0; i < n; i++) gg = i * i; return gg; }",
            "assert(f(8) == 49);" } },
        /* LoadLiteralObjV: a baked const literal materialized per iteration. */
        { OpCode::LoadLiteralObjV, {
            "func f(int n) {",
            "  var s = 0;",
            "  for (var i = 0; i < n; i++) { var a = [1, 2, 3]; s = s + a[0]; }",
            "  return s;",
            "}",
            "assert(f(runtime(5)) == 5);" } },
        /* ArrLen: the foreach snapshot bound over a proven array<int>. */
        { OpCode::ArrLen, {
            "func f(int n) {",
            "  var a = range(n);",
            "  var s = 0;",
            "  foreach (var x in a) s = s + x;",
            "  return s;",
            "}",
            "assert(f(runtime(5)) == 10);" } },
        /* DictLoadInt: a typed dict scalar read (member key, const pool). */
        { OpCode::DictLoadInt, {
            "func f(int n) {",
            "  var d = {\"a\": 10, \"b\": 20};",
            "  var s = 0;",
            "  for (var i = 0; i < n; i++) s = s + d.a;",
            "  return s;",
            "}",
            "assert(f(runtime(5)) == 50);" } },
        /* MakeClosureV: a per-iteration closure that CAPTURES the hot loop
         * accumulator `s`. Pins the N5 stale-cache bug: the capture snapshot
         * must read `s` from memory AFTER any register-cached value is flushed
         * (the fix disables caching for a run containing a MakeClosureV). g is
         * live after the loop (g()), so the reassignment isn't DCE'd. */
        { OpCode::MakeClosureV, {
            "func f(int n) {",
            "  var g = func() => 7;",
            "  var s = 0;",
            "  for (var i = 0; i < n; i++) {",
            "    g = func[s]() => s;",
            "    s = s + i;",
            "    s = s + i;",
            "  }",
            "  return s + g();",
            "}",
            "assert(f(runtime(4)) == 18);" } },
        /* BinOpV: a boxed (dyn) binary op `a + b` per iteration (the boxed_ops
         * pool path). */
        { OpCode::BinOpV, {
            "func f(int n) {",
            "  var dyn a = runtime(3); var dyn b = runtime(4);",
            "  var dyn acc = 0;",
            "  for (var i = 0; i < n; i++) { var dyn r = a + b; acc += r; }",
            "  return int(acc);",
            "}",
            "assert(f(runtime(5)) == 35);" } },
        /* CmpV: a boxed (dyn) comparison used as a VALUE `a < b`. */
        { OpCode::CmpV, {
            "func f(int n) {",
            "  var dyn a = runtime(3); var dyn b = runtime(4);",
            "  var dyn cnt = 0;",
            "  for (var i = 0; i < n; i++) { var dyn c = a < b; cnt += c; }",
            "  return int(cnt);",
            "}",
            "assert(f(runtime(5)) == 5);" } },
        /* CompoundV: a boxed (dyn) compound assign `s += a`. */
        { OpCode::CompoundV, {
            "func f(int n) {",
            "  var dyn a = runtime(3);",
            "  var dyn s = 0;",
            "  for (var i = 0; i < n; i++) { s += a; var j = i + 1; }",
            "  return int(s);",
            "}",
            "assert(f(runtime(5)) == 15);" } },
        /* LogV: a boxed (dyn) eager logical `a && b` used as a value. */
        { OpCode::LogV, {
            "func f(int n) {",
            "  var dyn a = runtime(1); var dyn b = runtime(1);",
            "  var dyn cnt = 0;",
            "  for (var i = 0; i < n; i++) { var dyn c = a && b; cnt += c; }",
            "  return int(cnt);",
            "}",
            "assert(f(runtime(5)) == 5);" } },
        /* CoerceNumV: the coerces_dyn accumulator - `s` is int, `s + d` is dyn
         * (int OP dyn), coerced back into the int slot each iteration. */
        { OpCode::CoerceNumV, {
            "func f(int n) {",
            "  var dyn d = runtime(3);",
            "  var s = 0;",
            "  for (var i = 0; i < n; i++) s = s + d;",
            "  return s;",
            "}",
            "assert(f(runtime(5)) == 15);" } },
        /* UnaryV: a boxed (dyn) unary `~a` (unary ~ is never M8-specialized).
         * ~5 = -6, accumulated 5x = -30. */
        { OpCode::UnaryV, {
            "func f(int n) {",
            "  var dyn a = runtime(5);",
            "  var dyn acc = 0;",
            "  for (var i = 0; i < n; i++) { var dyn r = ~a; acc += r; }",
            "  return int(acc);",
            "}",
            "assert(f(runtime(5)) == -30);" } },
        /* CallBuiltinV: a value-ABI builtin call `len(a)` per loop iteration.
         * The loop fragments (verified: the loop's builtin runs natively - a
         * count of 50 loop + 2 main's runtime/print for f(runtime(50))). NOTE:
         * main's own runtime()/print() are ALSO CallBuiltinV, so the counter
         * bumps regardless; the loop body (2 extra int ops) is there to keep the
         * body above MIN_RUN so it fragments and the LOOP builtin runs native. */
        { OpCode::CallBuiltinV, {
            "func f(int n) {",
            "  var dyn a = runtime(\"hello\");",
            "  var s = 0;",
            "  for (var i = 0; i < n; i++) {",
            "    var j = i + 1; var k = j + 1; s = s + len(a);",
            "  }",
            "  return s;",
            "}",
            "assert(f(runtime(5)) == 25);" } },
        /* LoadCaptureV: a closure reads its captured value each iteration. The
         * `base` capture is loaded (LoadCaptureV) then boxed-added per iter, so
         * the loop fragments and the capture read runs native. */
        { OpCode::LoadCaptureV, {
            "func mk(dyn base) {",
            "  return func [base] (int n) {",
            "    var dyn s = 0;",
            "    for (var i = 0; i < n; i++) s = s + base;",
            "    return s;",
            "  };",
            "}",
            "var f = mk(runtime(7));",
            "assert(f(runtime(5)) == 35);" } },
        /* Halt: a VOID function's implicit `return none` runs in the fragment.
         * f's whole body is a fully-native loop ending in Halt (no `return`),
         * so JIT-on it collapses to a single enter.nat - the Halt's
         * interpreted original is deleted, so the native Halt is the only
         * code. C4c: BOTH its arms (the callee's in-VM pop AND main's
         * boundary Halt) are now the emitted inline pop, so jit_halt
         * legitimately starves - the acceptance below takes g_jit_ret_inline
         * as "ran natively" for this op (the BinOpV inline-tier precedent). */
        { OpCode::Halt, {
            "func f(int n) { var s = 0; for (var i = 0; i < n; i++) s = s + i; }",
            "var r = f(runtime(5));",
            "assert(r == none);" } },
        /* LoadGlobalV: a function reads a (defined) global each loop iteration.
         * `s + g` loads g (LoadGlobalV) then adds it, so the loop fragments and
         * the global read runs native (the common defined-global path; the rare
         * undefined path bails to the interpreter - see the "use-before-def
         * global" tests entry). */
        { OpCode::LoadGlobalV, {
            "var g = 7;",
            "func f(int n) { var s = 0; for (var i = 0; i < n; i++) s = s + g;",
            "                return s; }",
            "assert(f(runtime(5)) == 35);" } },
        /* SliceV: a slice `a[0:2]` of a dyn string each loop iteration runs
         * native (jit_slice - the runtime Type::slice). The loop fragments (the
         * slice's original is kept - it re-raises, not op_fully_native - but the
         * fragment runs jit_slice). */
        { OpCode::SliceV, {
            "func f(dyn a, int n) {",
            "  var dyn last = a;",
            "  for (var i = 0; i < n; i++) last = a[0:2];",
            "  return last;",
            "}",
            "assert(f(runtime(\"hello\"), 5) == \"he\");" } },
        /* StoreElemValue: the UNIVERSAL subscript store `a[i] = v` on a dyn /
         * general array each loop iteration runs native (jit_store_elem_value ->
         * vm_subscript_store). The loop fragments; the store's original is kept
         * (re-raises / bails, not op_fully_native) but the fragment runs the
         * native helper. */
        { OpCode::StoreElemValue, {
            "func f(dyn a, int n) {",
            "  for (var i = 0; i < n; i++) a[i] = i * 2;",
            "  return a[3];",
            "}",
            "assert(f(runtime([0, 0, 0, 0, 0]), 5) == 6);" } },
        /* StoreMemberV: a struct field store `p.x = v` on a PROVEN struct base
         * each loop iteration runs native (jit_store_member -> vm_member_store;
         * the member key + carets from the baked member_keys pool). */
        { OpCode::StoreMemberV, {
            "struct P { int x; int y; }",
            "func f(P p, int n) {",
            "  for (var i = 0; i < n; i++) p.x = i * 2;",
            "  return p.x;",
            "}",
            "assert(f(P(0, 0), 5) == 8);" } },
        /* StoreElem2V: a 2-level nested store `a[i][j] = v` each iteration runs
         * native (jit_store_elem2 -> vm_nested_subscript_store). */
        { OpCode::StoreElem2V, {
            "func f(dyn a, int n) {",
            "  for (var i = 0; i < n; i++) a[i][0] = i * 2;",
            "  return a[2][0];",
            "}",
            "assert(f(runtime([[0], [0], [0]]), 3) == 4);" } },
        /* StoreElemChainV: a GENERIC N-level nested store `a[i][0][0] = v`
         * (3 levels) runs native (jit_store_elem_chain -> vm_chain_store_op). */
        { OpCode::StoreElemChainV, {
            "func f(dyn a, int n) {",
            "  for (var i = 0; i < n; i++) a[i][0][0] = i * 2;",
            "  return a[2][0][0];",
            "}",
            "assert(f(runtime([[[0]], [[0]], [[0]]]), 3) == 4);" } },
        /* StoreLValueChainV: a mixed subscript+member store `a[i].x = v` on a
         * BOXED struct runs native (jit_store_lvalue_chain -> the refactored
         * vm_chain_lvalue_store_op with the baked chain_steps + member_keys). */
        { OpCode::StoreLValueChainV, {
            "struct B { dyn x; }",
            "func f(dyn a, int n) {",
            "  for (var i = 0; i < n; i++) a[i].x = i * 2;",
            "  return a[2].x;",
            "}",
            "assert(f(runtime([B(0), B(0), B(0)]), 3) == 4);" } },
        /* StoreCaptureV: a closure reassigns its captured value (PLAIN `c = v`)
         * each loop iteration - runs native (jit_store_capture; a capture is
         * always defined, never throws). */
        { OpCode::StoreCaptureV, {
            "func mk(dyn c) {",
            "  return func [c] (int n) {",
            "    for (var i = 0; i < n; i++) c = i * 2;",
            "    return c;",
            "  };",
            "}",
            "var f = mk(runtime(0));",
            "assert(f(runtime(5)) == 8);" } },
        /* StoreGlobalV COMPOUND `g += i`: the rhs + slot ride the boxed_ops pool,
         * jit_store_global_compound runs num_bin_op each iter. Counter (shared
         * with the plain form) bumps from the compound helper. */
        { OpCode::StoreGlobalV, {
            "var g = 0;",
            "func f(int n) { for (var i = 0; i < n; i++) g += i; return g; }",
            "assert(f(runtime(5)) == 10);" } },
        /* StoreCaptureV COMPOUND `c += i`: jit_store_capture_compound (no bail -
         * a capture is always defined). */
        { OpCode::StoreCaptureV, {
            "func mk(dyn c) {",
            "  return func [c] (int n) {",
            "    for (var i = 0; i < n; i++) c += i;",
            "    return c;",
            "  };",
            "}",
            "var f = mk(runtime(0));",
            "assert(f(runtime(5)) == 10);" } },
        /* AppendV: `append(a, x)` each loop iteration runs native (jit_append ->
         * the never-throwing arr_append_fast fast path). */
        { OpCode::AppendV, {
            "func f(dyn a, int n) {",
            "  for (var i = 0; i < n; i++) append(a, i * 2);",
            "  return a[3];",
            "}",
            "assert(f(runtime([]), 5) == 6);" } },
        /* CallBuiltinLV: a mutating lvalue-ABI builtin (insert/pop) each loop
         * iteration runs native (jit_call_builtin_lv -> vm_call_builtin_lv_rest
         * for insert, func_lv for pop). `dyn a` keeps arg0 a runtime lvalue. */
        { OpCode::CallBuiltinLV, {
            "func f(dyn a, int n) {",
            "  for (var i = 0; i < n; i++) { insert(a, 0, i); pop(a); }",
            "  return len(a);",
            "}",
            "assert(f(runtime([1, 2, 3]), 20) == 3);" } },
        /* CallBuiltinLVElem: a mutating builtin whose arg0 is a SUBSCRIPT target
         * `append(rows[k], v)`; the helper forms the element LValue* via the
         * runtime Type::subscript, then func_lv. `dyn rows` keeps it a runtime
         * subscript. */
        { OpCode::CallBuiltinLVElem, {
            "func f(dyn rows, int n) {",
            "  for (var i = 0; i < n; i++) append(rows[i % 3], i);",
            "  return len(rows[0]) + len(rows[1]) + len(rows[2]);",
            "}",
            "assert(f(runtime([[], [], []]), 30) == 30);" } },
        /* CallBuiltinLVMember: a mutating builtin whose arg0 is a struct-MEMBER
         * target `append(b.items, v)`; the helper forms the boxed field LValue*
         * via vm_member_lvalue. A PROVEN struct base (`Bag b`) is required for the
         * op (a dyn/dict base takes the MemberV+AppendV path). */
        { OpCode::CallBuiltinLVMember, {
            "struct Bag { array<int> items; int tag; }",
            "func f(Bag b, int n) {",
            "  for (var i = 0; i < n; i++) append(b.items, i);",
            "  return len(b.items);",
            "}",
            "assert(f(Bag([], 0), 25) == 25);" } },
        /* MakeArrayV: a per-iteration array LITERAL `[i, i * 2]` builds natively
         * (jit_make_array -> build_array_from_values, flat int storage here). */
        { OpCode::MakeArrayV, {
            "func f(int n) {",
            "  var s = 0;",
            "  for (var i = 0; i < n; i++) { var p = [i, i * 2]; s += p[1]; }",
            "  return s;",
            "}",
            "assert(f(runtime(10)) == 90);" } },
        /* MakeDictV: a per-iteration dict LITERAL `{i: i * 2}` builds natively
         * (jit_make_dict -> build_dict_from_pairs over the interleaved run). */
        { OpCode::MakeDictV, {
            "func f(int n) {",
            "  var s = 0;",
            "  for (var i = 0; i < n; i++) { var d = {i: i * 2}; s += d[i]; }",
            "  return s;",
            "}",
            "assert(f(runtime(10)) == 90);" } },
        /* StructCtorV: a per-iteration POD struct construction `P(i, i * 2)`
         * builds natively (jit_struct_ctor, incl. the H1 dst-slot reuse). */
        { OpCode::StructCtorV, {
            "struct P { int x; int y; }",
            "func f(int n) {",
            "  var s = 0;",
            "  for (var i = 0; i < n; i++) { var p = P(i, i * 2); s += p.y; }",
            "  return s;",
            "}",
            "assert(f(runtime(10)) == 90);" } },
        /* StructCtorBoxedV: a NON-POD construction (B has an `opt` field) with a
         * runtime arg -> jit_struct_ctor_boxed (per-arg carets from the pool). */
        { OpCode::StructCtorBoxedV, {
            "struct B { dyn? v; int t; }",
            "func f(dyn a, int n) {",
            "  var s = 0;",
            "  for (var i = 0; i < n; i++) { var b = B(a, i); s += b.t; }",
            "  return s;",
            "}",
            "assert(f(runtime(\"z\"), 10) == 45);" } },
        /* JumpUnlessTrueV: the BOXED condition branch. jit_is_true evaluates
         * the condition and the FRAGMENT jumps, so a loop body holding one no
         * longer splits the run - which is what lets the loads below run on
         * EVERY iteration instead of only the loop-entry copy (the same loop
         * bumped LoadElemBool once for a 100-element array before this op). */
        { OpCode::JumpUnlessTrueV, {
            "func f(array<bool> a) {",
            "  var n = 0;",
            "  foreach (var b in a) { if (b == true) n += 1; }",
            "  return n;",
            "}",
            "assert(f(runtime([true, false, true, true])) == 3);" } },
        /* The FOREACH element/field loads. Each runs its loop natively with the
         * index materialized cache-aware into a register before the helper.
         * SHAPE NOTES (each verified with a per-op counter, since these ops are
         * op_fully_native and their originals are DELETED - `-vd`/`-vdj` show
         * only the enter.nat, so the counter is the ONLY evidence):
         *  - the struct ops need a PROVEN `array<S>` container; a `dyn` one
         *    routes to ForeachDynInit/Next instead and never reaches them;
         *  - `s += p.x` FUSES into StructFieldAddInt (#9), so the field-read
         *    test uses a non-accumulator body;
         *  - a body with a BOXED branch (`if (b == true)` -> JumpUnlessTrueV,
         *    still un-nativized) splits the run so only the loop-ENTRY copy is
         *    native and the counter stops scaling with iterations - the bodies
         *    below are branch-free so the whole loop runs native. */
        /* LoadElemValue: a general-array element bound into the loop var. */
        { OpCode::LoadElemValue, {
            "func f(array<array<int>> a) {",
            "  var dyn last = 0;",
            "  foreach (var e in a) last = e;",
            "  return last[0];",
            "}",
            "assert(f(runtime([[1], [2], [3]])) == 3);" } },
        /* LoadElemBool: a flat array<bool> element binds as a REAL bool. */
        { OpCode::LoadElemBool, {
            "func f(array<bool> a) {",
            "  var n = 0;",
            "  foreach (var b in a) n += int(b);",
            "  return n;",
            "}",
            "assert(f(runtime([true, false, true, true])) == 3);" } },
        /* StrLen + LoadStrChar: a foreach over a proven string (StrLen is the
         * once-evaluated bound, LoadStrChar binds each 1-char string). */
        { OpCode::StrLen, {
            "func f(str s) {",
            "  var n = 0;",
            "  foreach (var c in s) n += len(c);",
            "  return n;",
            "}",
            "assert(f(runtime(\"banana\")) == 6);" } },
        { OpCode::LoadStrChar, {
            "func f(str s) {",
            "  var n = 0;",
            "  foreach (var c in s) n += len(c);",
            "  return n;",
            "}",
            "assert(f(runtime(\"bob\")) == 3);" } },
        /* LoadStructFieldInt/Float: a flat array<PodStruct> foreach whose body
         * reads ONLY scalar fields - the direct byte read, no StructObject. */
        { OpCode::LoadStructFieldInt, {
            "struct S { int x; float y; }",
            "func f(array<S> a) {",
            "  var s = 0;",
            "  foreach (var p in a) { if (p.x > 1) s += 1; }",
            "  return s;",
            "}",
            "assert(f(runtime([S(1, 1.5), S(2, 2.5), S(3, 3.5)])) == 2);" } },
        { OpCode::LoadStructFieldFloat, {
            "struct S2 { int x; float y; }",
            "func f(array<S2> a) {",
            "  var s = 0.0;",
            "  foreach (var p in a) { var d = p.y * 2.0; s += d; }",
            "  return s;",
            "}",
            "assert(f(runtime([S2(1, 1.5), S2(2, 2.5)])) == 8.0);" } },
        /* LoadStructElemV: the WHOLE-`p` foreach bind (p used as a value, not
         * only as scalar fields) - a fresh StructObject per iteration. */
        { OpCode::LoadStructElemV, {
            "struct S3 { int x; int y; }",
            "func f(array<S3> a) {",
            "  var dyn last = 0;",
            "  foreach (var p in a) last = p;",
            "  return last.x;",
            "}",
            "assert(f(runtime([S3(1, 2), S3(7, 8)])) == 7);" } },
        /* MakeStructArrayV: the FUSED flat array<PodStruct> literal - two
         * same-def POD ctors with all-scalar args -> jit_make_struct_array. */
        { OpCode::MakeStructArrayV, {
            "struct Q { int x; int y; }",
            "func f(int n) {",
            "  var s = 0;",
            "  for (var i = 0; i < n; i++) {",
            "    var a = [Q(i, i * 2), Q(i + 1, 0)];",
            "    s += a[0].y + a[1].x;",
            "  }",
            "  return s;",
            "}",
            "assert(f(runtime(10)) == 145);" } },
        /* The ITERATOR ops. DictIter*: a foreach over a PROVEN dict (the
         * template instance pins the Dict type - the SHAPE TRAP again: a
         * `runtime({..})` arg is DYN and routes to ForeachDyn instead, so the
         * runtime() must wrap a VALUE, keeping the dict type proven); the
         * whole loop - init, the per-iteration next + the int body - runs in
         * one fragment (both ops are op_fully_native, so the body DELETES to
         * one enter.nat and the counter is the only evidence). */
        { OpCode::DictIterInit, {
            "func f(d) {",
            "  var s = 0;",
            "  foreach (k, v in d) s = s + v;",
            "  return s;",
            "}",
            "var d = {\"a\": runtime(1), \"b\": 2, \"c\": 3};",
            "assert(f(d) == 6);" } },
        { OpCode::DictIterNext, {
            "func f(d) {",
            "  var s = 0;",
            "  foreach (k, v in d) s = s + v;",
            "  return s;",
            "}",
            "var d = {\"x\": runtime(10), \"y\": 20};",
            "assert(f(d) == 30);" } },
        /* ForeachDyn*: a foreach over a DYN container (runtime array-vs-dict
         * dispatch). The same body handles both - run it over each. */
        { OpCode::ForeachDynInit, {
            "func f(dyn c) {",
            "  var s = 0;",
            "  foreach (x in c) s = s + x;",
            "  return s;",
            "}",
            "assert(f(runtime([10, 20, 30])) == 60);" } },
        { OpCode::ForeachDynNext, {
            "func f(dyn c) {",
            "  var s = 0;",
            "  foreach (k, v in c) s = s + v;",
            "  return s;",
            "}",
            "assert(f(runtime({\"a\": 5, \"b\": 6})) == 11);" } },
        /* The THROWING generic-IntBin arms (div/mod/reg-shifts) - emitted
         * INLINE (cqo+idiv / the shared reg-shift core); only these arms bump
         * the IntBin counter (the non-throwing arms don't), so the counter
         * attributes precisely. Division/mod stay generic IntBin (no
         * specialized shape); `1 << i` is the lit-first generic shl; `>>>`
         * has no specialized shape at all. */
        { OpCode::IntBin, {
            "func f(int n, int c) {",
            "  var s = 0;",
            "  for (var i = 1; i <= n; i++) s = s + i / c + i % c;",
            "  return s;",
            "}",
            "assert(f(runtime(10), 3) == 25);" } },
        { OpCode::IntBin, {
            "func f(int n) {",
            "  var s = 0;",
            "  for (var i = 0; i < n; i++) s = s + (1 << i) + (s >>> i);",
            "  return s;",
            "}",
            "assert(f(runtime(5)) == 31);" } },
        /* the div0 RAISE path (JR_DIV0), script-caught: the fragment stores
         * the kind + exits, EnterNative raises DivisionByZeroEx (caret from
         * the loc side table) and the same-frame handler catches it. */
        { OpCode::IntBin, {
            "func f(int a, int c) {",
            "  var r = 0;",
            "  try { r = a / c; } catch (DivisionByZeroEx) { r = 77; }",
            "  return r;",
            "}",
            "assert(f(9, runtime(0)) == 77);" } },
        /* LoadMemberInt/Float: the H1 typed STANDALONE struct-member read
         * (a local `p`, not a foreach-array element - that is
         * LoadStructFieldInt's shape). The body avoids `s += p.x` (the
         * StructFieldAddInt fusion) via a non-accumulator use. */
        /* LoadMemberInt/Float: a BOXED struct (the array field) keeps the
         * baked offset unavailable (b_dual_lo == -1), so the read runs the
         * generic HELPER - the path this counter proves. The baked POD fast
         * path is proven separately by jit_struct_baked (g_jit_member_fast,
         * bumped by the emitted inline code). */
        { OpCode::LoadMemberInt, {
            "struct M { int x; float y; array a; }",
            "func f(int n) {",
            "  var s = 0;",
            "  for (var i = 0; i < n; i++) {",
            "    var p = M(i, 1.5, []);",
            "    var t = p.x * 2;",
            "    s += t;",
            "  }",
            "  return s;",
            "}",
            "assert(f(runtime(5)) == 20);" } },
        { OpCode::LoadMemberFloat, {
            "struct M2 { int x; float y; array a; }",
            "func f(int n) {",
            "  var s = 0.0;",
            "  for (var i = 0; i < n; i++) {",
            "    var p = M2(i, 1.5, []);",
            "    var t = p.y * 2.0;",
            "    s += t;",
            "  }",
            "  return s;",
            "}",
            "assert(f(runtime(4)) == 12.0);" } },
        /* FloatBin div: inline divsd behind the sign-stripped divisor bits
         * test (+-0.0 raises DivisionByZeroEx, NaN/inf divide). Only the div
         * arm bumps the counter. */
        { OpCode::FloatBin, {
            "func f(float n) {",
            "  var s = 0.0;",
            "  for (var x = 1.0; x <= n; x += 1.0) s = s + 1.0 / x;",
            "  return s;",
            "}",
            "assert(f(runtime(2.0)) == 1.5);" } },
        { OpCode::FloatBin, {
            "func f(float a, float c) {",
            "  var r = 0.0;",
            "  try { r = a / c; } catch (DivisionByZeroEx) { r = 77.0; }",
            "  return r;",
            "}",
            "assert(f(9.0, runtime(0.0)) == 77.0);",
            "assert(f(9.0, runtime(-0.0)) == 77.0);",
            "assert(f(9.0, runtime(4.5)) == 2.0);" } },
        /* FloatBin mod: the same +-0.0 divisor test, then the exact fmod
         * LIBM call TypeFloat::mod makes (byte-identical NaN/inf results);
         * a 0.0 divisor raises DivisionByZeroEx like div. */
        { OpCode::FloatBin, {
            "func f(int n) {",
            "  var s = 0.0;",
            "  for (var i = 0; i < n; i++) s += (i * 1.5) % (0.7 + i);",
            "  return s;",
            "}",
            "assert(f(runtime(3)) < 1.80001 && f(runtime(3)) > 1.79999);",
            "func g(float a, float c) {",
            "  var r = 0.0;",
            "  try { r = a % c; } catch (DivisionByZeroEx) { r = 88.0; }",
            "  return r;",
            "}",
            "assert(g(9.5, runtime(0.0)) == 88.0);",
            "assert(g(9.5, runtime(4.0)) == 1.5);" } },
        /* StructFieldAddInt: the #9 struct-reduction fusion - fires on the
         * FOREACH-over-flat-struct-array chain `s = (s + p.x + p.y) % k`
         * (the fused base/index are the foreach snapshot + counter; a
         * hand-written `for i: s = s + a[i].x` lowers boxed instead - the
         * shape trap, caught by the counter). The read runs via the helper,
         * the add + write in the fragment. */
        { OpCode::StructFieldAddInt, {
            "struct FS { int x; int y; }",
            "func f(array<FS> a) {",
            "  var s = 0;",
            "  foreach (var p in a) s = (s + p.x + p.y) % 1000;",
            "  return s;",
            "}",
            "assert(f(runtime([FS(1, 9), FS(2, 9), FS(3, 9)])) == 33);" } },
        /* ForStepElemInt: the #9 back-edge `a[i]` load fused into the step.
         * SHAPE: a foreach whose body is the checksum `s = (s + x) % k`
         * (IntAddModRI) - a plain `s += a[i]` is claimed by the IntAddStep
         * fusion instead and never emits this op (the shape trap, caught by
         * the counter). */
        { OpCode::ForStepElemInt, {
            "func f(array<int> a) {",
            "  var s = 0;",
            "  foreach (var x in a) s = (s + x) % 1000000007;",
            "  return s;",
            "}",
            "assert(f(runtime([10, 20, 30, 40])) == 100);" } },
        /* EmplaceStruct: append(struct_arr, Ctor(args)) - construct-in-place
         * into the flat array's bytes. */
        { OpCode::EmplaceStruct, {
            "struct ES { int x; int y; }",
            "func f(int n) {",
            "  var a = [ES(0, 0)];",
            "  for (var i = 1; i < n; i++) append(a, ES(i, i * 2));",
            "  var s = 0;",
            "  for (var i = 0; i < len(a); i++) s = s + a[i].y;",
            "  return s;",
            "}",
            "assert(f(runtime(5)) == 20);" } },
        /* JumpIfNotNoneV: the `??` short-circuit branch (an inline none-tag
         * compare) - both the none and the non-none paths. */
        { OpCode::JumpIfNotNoneV, {
            "func co(opt dyn v, int n) {",
            "  var s = 0;",
            "  for (var i = 0; i < n; i++) { var dyn r = v ?? 7; s += int(r); }",
            "  return s;",
            "}",
            "assert(co(runtime(none), 3) == 21);",
            "assert(co(runtime(2), 3) == 6);" } },
        /* CmpFloatV: the typed float compare-to-bool VALUE (a float sort
         * comparator's body) - inline swapped ucomisd + setcc. */
        { OpCode::CmpFloatV, {
            "func f(float a, float b, int n) {",
            "  var c = 0;",
            "  for (var i = 0; i < n; i++) {",
            "    var t = a < b;",
            "    if (t) c += 1;",
            "  }",
            "  return c;",
            "}",
            "assert(f(runtime(1.5), runtime(2.5), 4) == 4);",
            "assert(f(runtime(2.5), runtime(1.5), 4) == 0);" } },
        /* DeclConstV: a const container decl in a loop body (re-bound each
         * iteration as a CONST LValue; reads of it fold, the bind op stays). */
        { OpCode::DeclConstV, {
            "func f(int n) {",
            "  var s = 0;",
            "  for (var i = 0; i < n; i++) {",
            "    const c = [1, 2];",
            "    s += c[0];",
            "  }",
            "  return s;",
            "}",
            "assert(f(runtime(5)) == 5);" } },
        /* DefinedGlobalV: defined(g) of a GLOBAL reads the slot's
         * defined-flag. */
        { OpCode::DefinedGlobalV, {
            "var g = 1;",
            "func rd() { return g; }",
            "func f(int n) {",
            "  var c = 0;",
            "  for (var i = 0; i < n; i++) { if (defined(g)) c += 1; }",
            "  return c;",
            "}",
            "assert(f(runtime(4)) == 4);",
            "assert(rd() == 1);" } },
        /* The STRICT-unpack family: the foreach 2-var unpack over proven
         * array<array<T>> (int/float/value), the `_` targets variant, and
         * the multi-assign MultiUnpackV. */
        { OpCode::UnpackElemInt, {
            "func f(array<array<int>> a) {",
            "  var s = 0;",
            "  foreach (x, y in a) s = s + x * y;",
            "  return s;",
            "}",
            "assert(f(runtime([[1, 2], [3, 4]])) == 14);" } },
        { OpCode::UnpackElemFloat, {
            "func f(array<array<float>> a) {",
            "  var s = 0.0;",
            "  foreach (x, y in a) s = s + x * y;",
            "  return s;",
            "}",
            "assert(f(runtime([[1.5, 2.0], [0.5, 4.0]])) == 5.0);" } },
        { OpCode::UnpackElemValue, {
            "func f(array<array<str>> a) {",
            "  var s = \"\";",
            "  foreach (x, y in a) s = s + x + y;",
            "  return s;",
            "}",
            "assert(f(runtime([[\"a\", \"b\"], [\"c\", \"d\"]])) ==",
            "       \"abcd\");" } },
        { OpCode::UnpackElemTargets, {
            "func f(array<array<int>> a) {",
            "  var s = 0;",
            "  foreach (x, _, z in a) s = s + x + z;",
            "  return s;",
            "}",
            "assert(f(runtime([[1, 9, 2], [3, 9, 4]])) == 10);" } },
        /* typed targets (the unpack_coerce pool path): a dyn rvalue
         * destructured into int locals per iteration. (Bare `var a, b = p`
         * with a dyn rvalue is a compile-time DynRequiredEx.) */
        { OpCode::MultiUnpackV, {
            "func f(dyn p, int n) {",
            "  var s = 0;",
            "  int a = 0; int b = 0;",
            "  for (var i = 0; i < n; i++) {",
            "    a, b = p;",
            "    s += a + b;",
            "  }",
            "  return s;",
            "}",
            "assert(f(runtime([3, 4]), 5) == 35);" } },
        /* a strict-length unpack throw from the fragment, script-caught. */
        { OpCode::MultiUnpackV, {
            "func f(dyn p) {",
            "  var r = 0;",
            "  int a = 0; int b = 0;",
            "  try { a, b = p; r = a + b; }",
            "  catch (TypeErrorEx) { r = 42; }",
            "  return r;",
            "}",
            "assert(f(runtime([1, 2, 3])) == 42);" } },
        /* The CHECKED INC-DEC family: a dyn scalar, a dyn element, a dyn
         * member, and the impure-lvalue chain VALUE form. */
        { OpCode::IncDecCheckedV, {
            "func f(dyn d, int n) {",
            "  for (var i = 0; i < n; i++) d++;",
            "  return d;",
            "}",
            "assert(f(runtime(10), 5) == 15);" } },
        { OpCode::IncDecElemCheckedV, {
            "func f(dyn c, int n) {",
            "  for (var i = 0; i < n; i++) c[\"k\"]++;",
            "  return c[\"k\"];",
            "}",
            "assert(f(runtime({\"k\": 3}), 4) == 7);" } },
        { OpCode::IncDecMemberCheckedV, {
            "func f(dyn c, int n) {",
            "  for (var i = 0; i < n; i++) c.k--;",
            "  return c.k;",
            "}",
            "assert(f(runtime({\"k\": 9}), 4) == 5);" } },
        { OpCode::IncDecChainV, {
            "func k(int i) => 0;",
            "func f(array<int> a, int n) {",
            "  var s = 0;",
            "  for (var i = 0; i < n; i++) s += a[k(i)]++;",
            "  return s;",
            "}",
            "assert(f(runtime([10, 20]), 3) == 33);" } },
        /* the scalar checked throw path, script-caught (a string ++). */
        { OpCode::IncDecCheckedV, {
            "func f(dyn d) {",
            "  var r = 0;",
            "  try { d++; r = 1; } catch (TypeErrorEx) { r = 8; }",
            "  return r;",
            "}",
            "assert(f(runtime(\"nope\")) == 8);" } },
        /* M5: the SYNC native call - a plain CallV to a NON-leaf callee
         * (a loop body -> multi-run, never native_leaf), from MAIN (which
         * the #55 direct call never covered). The caller's loop continues
         * natively across the call. */
        { OpCode::CallV, {
            "func f(int a, int b) {",
            "  var s = a;",
            "  for (var i = 0; i < 3; i++) s += b;",
            "  return s;",
            "}",
            "var t = 0;",
            "for (var k = 0; k < 4; k++) t += f(k, runtime(2));",
            "assert(t == 30);" } },
        /* the sync call's throw path: a callee div0 dispatches to the
         * CALLER's same-frame handler via g_vm_jit_exc. */
        { OpCode::CallV, {
            "var gsink = 0;",
            "func d(int a, dyn b) { gsink = a; return a / b; }",
            "func f(int n) {",
            "  var c = 0;",
            "  for (var i = 0; i < n; i++) {",
            "    try { c += d(i, 0); } catch (DivisionByZeroEx) { c += 1; }",
            "  }",
            "  return c;",
            "}",
            "assert(f(runtime(4)) == 4);" } },
        /* the DEPTH CAP: deep PLAIN-CallV recursion (impure - no pure-call
         * cache, no CachedCallV) bails the deep tail to the interpreted
         * call's flat in-VM stack - no C-stack overflow. */
        { OpCode::CallV, {
            "var gg = 0;",
            "func r(int n) {",
            "  gg = n;",
            "  if (n == 0) { return 0; }",
            "  return r(n - 1);",
            "}",
            "assert(r(runtime(10000)) == 0);",
            "assert(gg == 0);" } },
        /* Step 7a - the INLINE simple exception ops: the hot NO-THROW try
         * path (handler push/pop per entry/exit) and the finally pend
         * flag. (The helper-call form was measured +8% and reverted; these
         * counters prove the INLINE forms run.) */
        { OpCode::PushHandler, {
            "func f(int n) {",
            "  var s = 0;",
            "  for (var i = 0; i < n; i++) {",
            "    try { s += i; } catch (TypeErrorEx) { s = -1; }",
            "  }",
            "  return s;",
            "}",
            "assert(f(runtime(5)) == 10);" } },
        { OpCode::PopHandler, {
            "func f(int n) {",
            "  var s = 0;",
            "  for (var i = 0; i < n; i++) {",
            "    try { s += i; } catch (TypeErrorEx) { s = -1; }",
            "  }",
            "  return s;",
            "}",
            "assert(f(runtime(6)) == 15);" } },
        { OpCode::SetPend, {
            "func f(int n) {",
            "  var s = 0;",
            "  for (var i = 0; i < n; i++) {",
            "    try { s += i; } finally { s += 1; }",
            "  }",
            "  return s;",
            "}",
            "assert(f(runtime(4)) == 10);" } },
        /* a THROWING try under the inline handler push: the raise (still
         * interpreted) must dispatch to the pushed (remapped) catch pc. */
        { OpCode::PushHandler, {
            "func f(dyn d, int n) {",
            "  var s = 0;",
            "  for (var i = 0; i < n; i++) {",
            "    try { s += i / d; } catch (DivisionByZeroEx) { s += 100; }",
            "  }",
            "  return s;",
            "}",
            "assert(f(runtime(0), 3) == 300);" } },
        /* The iterator THROW paths, script-caught: a non-container init and a
         * strict-unpack next each ride g_vm_jit_exc out of the fragment and
         * dispatch to the same-frame handler. */
        { OpCode::ForeachDynInit, {
            "func f(dyn c) {",
            "  var r = 0;",
            "  try { foreach (x in c) r = 1; } catch (TypeErrorEx) { r = 2; }",
            "  return r;",
            "}",
            "assert(f(runtime(5)) == 2);" } },
        { OpCode::ForeachDynNext, {
            "func f(dyn c) {",
            "  var r = 0;",
            "  try { foreach (a, b in c) r = 1; }",
            "  catch (TypeErrorEx) { r = 9; }",
            "  return r;",
            "}",
            "assert(f(runtime([[1, 2, 3]])) == 9);" } },
        /* M5 inc 3 (LEAN SYNC ENTER): CachedCallV - the recursion-unroll's
         * frontier calls run sync from the caller's fragment; the cache
         * probe (hit AND miss + record-riding key store) both exercise. */
        { OpCode::CachedCallV, {
            "func fib(n) => n < 2 ? n : fib(n-1) + fib(n-2);",
            "var s = 0;",
            "for (var i = 0; i < 3; i++) s += fib(runtime(15));",
            "assert(s == 1830);" } },
        /* CachedCallV's throw path: the callee raises deep in the sync
         * NEST (each level a helper+dispatch), the walk stops at each sync
         * record, and the top CALLER's same-frame handler catches. (The
         * callee must stay PURE - n/(n-n) not n/runtime(0) - else it is
         * not cacheable and no CachedCallV exists at all.) */
        { OpCode::CachedCallV, {
            "func t(n) => n < 2 ? n / (n - n) : t(n-1) + t(n-2);",
            "var c = 0;",
            "for (var i = 0; i < 3; i++) {",
            "  try { c += t(runtime(5)); }",
            "  catch (DivisionByZeroEx) { c += 1; }",
            "}",
            "assert(c == 3);" } },
        /* CallValueV: an indirect func-VALUE call (a value-used lambda -
         * dispatched from an array, so no template redirect) runs sync. */
        { OpCode::CallValueV, {
            "var ops = [func (x) => x + 1, func (x) => x * 2];",
            "var s = 0;",
            "for (var i = 0; i < 6; i++) { var f = ops[i % 2]; s += f(i); }",
            "assert(s == 27);" } },
        /* CallValueV's throw path: the value-called lambda raises; the
         * sync conveyance dispatches the caller's same-frame handler. */
        { OpCode::CallValueV, {
            "var ops = [func (x) => x / (x - x)];",
            "var s = 0;",
            "for (var i = 0; i < 3; i++) {",
            "  var f = ops[0];",
            "  try { s += f(i); } catch (DivisionByZeroEx) { s += 2; }",
            "}",
            "assert(s == 6);" } },
        /* The map/filter pair (the last non-call island): the guard + the
         * shared vm_map_filter body (callback re-enters vm_dispatch). */
        { OpCode::MapFilterV, {
            "var a = [runtime(1), 2, 3, 4];",
            "var dyn s = 0;",
            "for (var i = 0; i < 3; i++) {",
            "  var m = map(func (x) => x * 2, a);",
            "  s = s + m[1];",
            "}",
            "assert(s == 12);" } },
        /* The dyn-callee generic call: a dyn BUILTIN callee dispatched by
         * Kind, and a dyn CLOSURE callee via the lean sync core. */
        { OpCode::CallValueGenericV, {
            "var dyn f = len;",
            "var s = 0;",
            "for (var i = 0; i < 5; i++) s += f([1, 2, i]);",
            "assert(s == 15);",
            "func mk(start) => func [start] { start++; return start; };",
            "var dyn c = mk(0);",
            "var t = 0;",
            "for (var i = 0; i < 4; i++) t += c();",
            "assert(t == 10);" } },
        /* CheckCallableV's throw: a dyn NON-callable callee raises
         * NotCallableEx with the callee caret BEFORE the args evaluate
         * (script-caught). */
        { OpCode::CheckCallableV, {
            "func f(dyn v, int n) {",
            "  var r = 0;",
            "  for (var i = 0; i < n; i++) {",
            "    try { var dyn q = v(i); r += 1; }",
            "    catch (NotCallableEx) { r += 2; }",
            "  }",
            "  return r;",
            "}",
            "assert(f(runtime(5), 3) == 6);" } },
        /* CheckFuncV's throw: a dyn non-func arg0 raises BEFORE arg1's
         * code runs, with arg0's caret (script-caught). */
        { OpCode::CheckFuncV, {
            "func f(dyn v, dyn a, int n) {",
            "  var r = 0;",
            "  for (var i = 0; i < n; i++) {",
            "    try { var m = map(v, a); r = 1; }",
            "    catch (TypeErrorEx) { r += 2; }",
            "  }",
            "  return r;",
            "}",
            "assert(f(runtime(5), runtime([1]), 3) == 6);" } },
    };
    for (const Case &c : cases) {
        const unsigned long b = g_jit_op_run[static_cast<size_t>(c.op)];
        const unsigned long bf = g_jit_boxed_fast;
        const unsigned long s2 = g_jit_store2_fast;
        const unsigned long ri = g_jit_ret_inline;
        if (!run(c.src)) {
            fprintf(stderr, "jit_op_nativized: op %d WRONG RESULT\n",
                    (int)c.op);
            return false;   /* wrong result (the program's assert threw) */
        }
        /* "ran natively" = the helper bumped g_jit_op_run OR (#60) the
         * emitted INT-INT INLINE tier served it - BinOpV/CmpV/CompoundV
         * with int operands never reach their helper anymore, which is
         * the deeper form of native, not a gap (g_jit_boxed_fast is
         * bumped by the emitted fast path itself). StoreElem2V joined
         * the same club with its #95 inline tier (g_jit_store2_fast). */
        const bool inline_ok =
            ((c.op == OpCode::BinOpV || c.op == OpCode::CmpV
              || c.op == OpCode::CompoundV)
             && g_jit_boxed_fast > bf)
            || (c.op == OpCode::StoreElem2V && g_jit_store2_fast > s2)
            /* C4c: Halt (and ReturnV) are served by the emitted inline
             * pop - jit_halt legitimately starves (both the in-VM and
             * the boundary arm are inline now). */
            || (c.op == OpCode::Halt && g_jit_ret_inline > ri);
        if (g_jit_op_run[static_cast<size_t>(c.op)] <= b && !inline_ok) {
            fprintf(stderr, "jit_op_nativized: op %d DID NOT RUN\n",
                    (int)c.op);
            return false;   /* the op's NATIVE code did NOT run - a real gap */
        }
    }
    /* ThrowRuntimeV: an always-throwing op is an unconditional native EXIT
     * (its exception mix includes non-Runtime ones the JIT cannot convey);
     * the interpreter re-runs the side-effect-free op and throws. The run
     * FAILS by design (UndefinedVariableEx is not script-catchable) - the
     * counter is the execution proof that the fragment reached the op. */
    {
        const unsigned long b =
            g_jit_op_run[static_cast<size_t>(OpCode::ThrowRuntimeV)];
        if (run({ "func f(int n) {",
                  "  var s = 0;",
                  "  for (var i = 0; i < n; i++) s += i;",
                  "  s += undefined_name;",
                  "  return s;",
                  "}",
                  "f(runtime(3));" })) {
            fprintf(stderr, "jit_op_nativized: ThrowRuntimeV case did not "
                            "throw\n");
            return false;
        }
        if (g_jit_op_run[static_cast<size_t>(OpCode::ThrowRuntimeV)] <= b) {
            fprintf(stderr,
                    "jit_op_nativized: ThrowRuntimeV DID NOT RUN\n");
            return false;
        }
    }
    return true;
#else
    return true;
#endif
}

static bool vm_codegen_shapes()
{
    /* 1) resolved-local int while + if -> native ops (native-first codegen
     * applies to top-level statements, not only loop bodies). Setup `var i/s=0`
     * -> LoadImm (not counted). */
    VmOpCounts a;
    if (!codegen_counts({
            "var i = 0;", "var s = 0;",
            "while (i < 5) { s += i; i += 1; }",
            "if (s > 3) s += 100; else s -= 1;",
        }, a))
        return false;
    /* native while: 1 JumpUnlessIntCmp + 2 IntBin (s+=i, i+=1); the if's cond
     * `s>3` is a native compare too (a 2nd JumpUnlessIntCmp) with 2 IntBin
     * branches (s+=100, s-=1) + a Jump over the else - no fallback; one
     * Halt. */
    const bool native_ok =
        a.juic == 2 && a.intbin == 4 &&
        a.jmp >= 1 && a.halt == 1;

    /* 2) a NESTED FUNC DECL in a loop body is NATIVE (MakeClosureV +
     * StoreGlobalV to its scoped-global slot, re-bound each iteration
     * exactly as the tree-walker re-evals the decl) - this was the last
     * REAL-code whole-loop fallback. The loop compiles: a JumpUnlessIntCmp
     * cond + an IntBin (i += 1), no EvalStmt. */
    VmOpCounts b;
    if (!codegen_counts({
            "var s = 0; var i = 0;",
            "while (i < 5) { func g() => 1; i += 1; }",
        }, b))
        return false;
    const bool fallback_ok =
        b.juic == 1 && b.intbin >= 1 && b.makeclosure >= 1;

    /* 2b) `show()` - the LAST node-ABI builtin - FOLDS at compile time
     * (fold_show_calls: a named function renders via render_func_code, a
     * non-identifier expression via render_construct_code, both -> a
     * LiteralStr), so it NEVER reaches codegen (there is no fallback op to
     * reach). Here the folded string makes the whole while-condition const
     * -> the loop DCEs / compiles with zero loop ops. */
    VmOpCounts b2;
    if (!codegen_counts({
            "func g2() => 1;",
            "var i = 0;",
            "while (len(show(g2)) < 0) { i += 1; }",
        }, b2))
        return false;
    /* codegen SUCCEEDING is the pin: an unfolded show() has no ABI and
     * would abort compilation (throw_not_lowered); the fold left only a
     * LiteralStr, so the loop lowers like any const-condition while. */
    const bool fallback_net_ok = b2.halt == 1;

    /* 3) a NESTED-expr plain assignment goes native and allocates a temp:
     * `s = i*i + 1` -> IntBin{t=i*i}, IntBin{s=t+1} (+ i++). */
    VmOpCounts c;
    if (!codegen_counts({
            "var i = 0; var s = 0;",
            "while (i < 5) { s = i*i + 1; i++; }",
        }, c))
        return false;
    const bool nested_ok =
        c.juic == 1 && c.intbin >= 3 && c.n_temps >= 1;

    /* 4) bool-safety: a plain assign of a BOOL value must NOT become a native
     * int-write (that would corrupt the bool slot). It stays a fallback
     * EvalStmt - safe (tree-walked) - while the native `i++` makes the loop go
     * native around it. The guarantee is exactly ONE IntBin (the `i++`): the
     * `b = flag` did NOT become a second, corrupting int-write. (`flag` folds
     * to `true`, a bool literal - definitely_int correctly rejects it.) */
    VmOpCounts d;
    if (!codegen_counts({
            "var flag = true; var b = false; var i = 0;",
            "while (i < 5) { b = flag; i++; }",
        }, d))
        return false;
    const bool bool_safe = d.juic == 1 && d.intbin == 1;

    /* 5) a pure-FLOAT loop compiles to the float register ops (FloatBin +
     * JumpUnlessFloatCmp), no fallback, no int ops. */
    VmOpCounts f;
    if (!codegen_counts({
            "var x = 0.0; var s = 0.0;",
            "while (x < 5.0) { s = s + x*x; x += 1.0; }",
        }, f))
        return false;
    const bool float_ok =
        f.jufc == 1 && f.fbin >= 3
        && f.juic == 0 && f.intbin == 0;

    /* 6) a MIXED int/float loop compiles per-statement: an int condition + an
     * int counter (IntBin) and a float accumulator (FloatBin), no fallback. */
    VmOpCounts m;
    if (!codegen_counts({
            "var i = 0; var f = 0.0;",
            "while (i < 5) { f += 0.5; i++; }",
        }, m))
        return false;
    const bool mixed_ok =
        m.juic == 1 && m.jufc == 0 && m.intbin == 1 && m.fbin == 1;

    /* 7) a counted `for` compiles to the fused register loop: an initial
     * JumpUnlessIntCmp + the back edge - which for an accumulate body is
     * the #9 IntAddStep superinstruction (the trailing `s += t` fused
     * INTO the step; the body's `t = i*i` stays an IntBin). */
    VmOpCounts g;
    if (!codegen_counts({
            "var s = 0;",
            "for (var i = 0; i < 10; i++) s += i*i;",
        }, g))
        return false;
    const bool for_ok =
        g.iaddstep == 1 && g.flstep == 0 && g.juic == 1
        && g.intbin >= 1 && g.jmp == 0;

    /* 8) a DECL with an arith rvalue inside a loop body compiles natively (the
     * register machine treats `var t = <int expr>` like a plain assign to t's
     * frame slot) - no fallback. */
    VmOpCounts h;
    if (!codegen_counts({
            "var i = 0; var s = 0;",
            "while (i < 5) { var t = i*2; s += t; i++; }",
        }, h))
        return false;
    const bool decl_ok =
        h.juic == 1 && h.intbin >= 3;

    /* 9) an array-element READ `a[i]` in a loop compiles to a native LoadElemInt
     * (no fallback for the read), and the float element variant to LoadElemFloat
     * (Phase 5). */
    VmOpCounts ai;
    if (!codegen_counts({
            "var a = [10, 20, 30, 40, 50]; var s = 0;",
            "for (var i = 0; i < 5; i++) s += a[i];",
        }, ai))
        return false;
    const bool read_int_ok =
        ai.loadei == 1 && ai.iaddstep == 1 && ai.flstep == 0;

    VmOpCounts af;
    if (!codegen_counts({
            "var a = [1.5, 2.5, 3.5]; var s = 0.0;",
            "for (var i = 0; i < 3; i++) s += a[i];",
        }, af))
        return false;
    const bool read_flt_ok =
        af.loadef == 1 && af.flstep == 1 && af.fbin >= 1;

    /* 10) an array-element WRITE `a[i] = expr` compiles to a native StoreElemInt
     * (int) / StoreElemFloat (float), with the read still a LoadElem (Phase 5). */
    VmOpCounts wi;
    if (!codegen_counts({
            "var a = array(5, 0);",
            "for (var i = 0; i < 5; i++) a[i] = i*2;",
        }, wi))
        return false;
    const bool write_int_ok =
        wi.storei == 1 && wi.flstep == 1 && wi.loadei == 0;

    VmOpCounts wf;
    if (!codegen_counts({
            "var a = array(3, 0.0);",
            "for (var i = 0; i < 3; i++) a[i] = i*1.5;",
        }, wf))
        return false;
    const bool write_flt_ok =
        wf.storef == 1 && wf.flstep == 1;

    /* 11) NESTED loops + an `if` in a loop body compile fully native - two
     * ForLoopStep (outer+inner), no EvalStmt in the hot path. The `if` here
     * has a comparison condition, so it is a native JumpUnlessIntCmp (an
     * fallback op even exists - zero-AST by construction). */
    VmOpCounts nl;
    if (!codegen_counts({
            "var a = array(10, 0); var s = 0;",
            "for (var i = 0; i < 10; i++)",
            "  for (var j = 0; j < 10; j++)",
            "    if (i < j) s += a[i];",
        }, nl))
        return false;
    const bool nested_native_ok =
        nl.flstep == 2 && nl.loadei == 1
        && nl.juic >= 1;

    /* 12) a COMPOUND array store `a[i] += b[i]` compiles native: one
     * StoreElemInt (the compound is an aop on it, not a separate load+store)
     * and one LoadElemInt for the b[i] read, no fallback. */
    VmOpCounts cs;
    if (!codegen_counts({
            "var a = array(5, 0); var b = [1,2,3,4,5];",
            "for (var i = 0; i < 5; i++) a[i] += b[i];",
        }, cs))
        return false;
    /* the back edge fuses the b[i] load (#9 ForStepElemInt); the
     * original load stays in place for the loop-entry path. */
    const bool compound_store_ok =
        cs.storei == 1 && cs.loadei == 1 && cs.forstepel == 1
        && cs.flstep == 0;

    /* 13) a 2-D read `m[i][j]` in nested loops lowers fully native, and the
     * INVARIANT row read `m[i]` is HOISTED out of the inner loop (LICM): it
     * becomes one SubscriptV into a `$licm0` temp above the inner loop, so the
     * inner body is a single LoadElemInt. The per-iteration LoadElemValue that
     * used to materialize the row - a boxed EvalValue + an intrusive_ptr
     * retain/release every iteration - is GONE (loadev == 0), which is the
     * whole point of the pass. Here `0 < 3` is decidable at compile time, so
     * no guard is emitted either (juic stays 2: the two loop tests). */
    VmOpCounts d2;
    if (!codegen_counts({
            "var m = [[1,2,3],[4,5,6]]; var s = 0;",
            "for (var i = 0; i < 2; i++)",
            "  for (var j = 0; j < 3; j++) s += m[i][j];",
        }, d2))
        return false;
    /* the inner `s += t` + step fuse to IntAddStep (#9); the outer
     * step stays a plain ForLoopStep. */
    const bool read_2d_ok =
        d2.loadev == 0 && d2.subscriptv == 1 && d2.loadei == 1
        && d2.flstep == 1 && d2.iaddstep == 1 && d2.juic == 2;

    /* 14) a scalar-returning migrated BUILTIN in a loop body (`s += sqrt(i)`)
     * lowers native - and a MATH builtin gets the typed MathFnV (F1), not
     * the generic CallBuiltinV marshal - plus a FloatBin for the +=, a
     * ForLoopStep, no fallback EvalStmt. A non-math builtin (`len`) keeps
     * CallBuiltinV (test 28). */
    VmOpCounts bd;
    if (!codegen_counts({
            "var s = 0.0;",
            "for (var i = 1; i < 10; i++) s += sqrt(i);",
        }, bd))
        return false;
    const bool builtin_dispatch_ok =
        bd.mathfnv == 1 && bd.callbuiltinv == 0 && bd.fbin == 1
        && bd.flstep == 1
       ;

    /* 14b) F1 coverage: every MathFn shape - 1-arg fns, `float(int)`,
     * `abs(float)` (fabs), 2-arg `pow` - lowers to MathFnV; `abs(int)`
     * (int result) and `float("3")` (string parse) DECLINE to the generic
     * builtin; a wrong-arity `pow(x)` declines (throws at runtime). */
    VmOpCounts mf;
    if (!codegen_counts({
            "var s = 0.0;",
            "for (var i = 1; i < 4; i++) {",
            "    var x = float(i);",
            "    s += sqrt(x) + pow(x, 2.0) + abs(0.0 - x) + floor(x);",
            "}",
        }, mf))
        return false;
    const bool mathfn_ok = mf.mathfnv == 5 && mf.callbuiltinv == 0;

    /* 14c) the E1-E4 PEEPHOLE (plans/archived/vm-peephole.md): a RUNTIME ternary's
     * arms produce STRAIGHT into the assignment's dst - the join-point
     * MoveV is eliminated by retargeting BOTH arm producers (liveness-
     * checked) - leaving one arm-skip Jump and zero moves. (The source
     * must be runtime: a const-foldable ternary disappears entirely, which
     * is the parser/AutoConst's job, not the peephole's.) */
    VmOpCounts pp;
    if (!codegen_counts({
            "var s = 0;",
            "for (var i = 0; i < 3; i++) {",
            "    var r = i < 2 ? i + 1 : i + 7;",
            "    s += r;",
            "}",
        }, pp))
        return false;
    const bool peephole_ok = pp.movev == 0 && pp.jmp == 1;

    /* 15) a native loop with a FLOW-FREE fallback body statement still goes
     * native INCLUDING a discarded `map(...)` statement: the loop-body
     * DISCARD tier compiles any expression statement into a scratch temp
     * and drops the result (map lowers via CheckFuncV + MapFilterV - its
     * validate-arg0-before-arg1 order preserved), so the counted `for`
     * (ForLoopStep) has NO fallback op - there is none to have. */
    VmOpCounts ab;
    if (!codegen_counts({
            "var s = 0; var a = [3, 1, 2];",
            "for (var i = 0; i < 5; i++) { s += i; map(func(e) => e, a); }",
        }, ab))
        return false;
    const bool array_build_ok =
        ab.flstep == 1 && ab.intbin >= 1 && ab.mapfilter == 1
        && ab.checkfunc == 1;

    /* 16) a GENERAL (non-range) `for` whose cond isn't the counted `i<bound`
     * shape (`f*f <= 100`) still compiles native, lowered to the while form: a
     * cond compare (JumpUnlessIntCmp), the body + inc IntBins, and a Jump back
     * - NOT a ForLoopStep (it isn't a counted loop), no fallback. */
    VmOpCounts gf;
    if (!codegen_counts({
            "var s = 0;",
            "for (var f = 2; f*f <= 100; f++) s += f;",
        }, gf))
        return false;
    const bool general_for_ok =
        gf.juic == 1 && gf.intbin >= 3 && gf.jmp >= 1 && gf.flstep == 0
       ;

    /* 17) break/continue in a native loop compile to native Jumps (Gap B), NOT
     * a whole-loop fallback: a counted `for` with `if(i==3) continue;` +
     * `if(i==7) break;` stays a ForLoopStep with two extra Jumps (the continue
     * + the break) and three JumpUnlessIntCmp (the loop test + the two ifs). */
    VmOpCounts bk;
    if (!codegen_counts({
            "var s = 0;",
            "for (var i=0; i<10; i++) { if (i==3) continue; if (i==7) break;"
            " s += i; }",
        }, bk))
        return false;
    /* The peephole INVERTS both flow jumps (branch-over-jump): `if(i==3)
     * continue;` becomes ONE `i.jmp.ifnot i != 3 -> for.step` - so ZERO
     * plain Jumps remain. */
    const bool break_cont_ok =
        bk.flstep == 1 && bk.jmp == 0 && bk.juic >= 3 && bk.intbin >= 1;

    /* 18) a COMPOUND loop condition `while (A && B)` lowers to one native
     * compare-branch per conjunct (both to the exit) - so
     * `while (i<10 && j<20)` is two JumpUnlessIntCmp, no fallback. */
    VmOpCounts cc;
    if (!codegen_counts({
            "var i = 0; var j = 0; var s = 0;",
            "while (i < 10 && j < 20) { s += i; i++; j += 2; }",
        }, cc))
        return false;
    const bool compound_cond_ok =
        cc.juic == 2 && cc.intbin >= 1;

    /* 19) the BOXED general-value path: `s = s + "x"` (a string-build loop)
     * lowers to native boxed ops (LoadConstV for "x", BinOpV for the concat via
     * num_bin_op) instead of a fallback EvalStmt - no eval.stmt for the assign,
     * and the for-loop stays counted. */
    VmOpCounts bx;
    if (!codegen_counts({
            "var s = \"\";",
            "for (var i = 0; i < 5; i++) { s = s + \"x\"; }",
        }, bx))
        return false;
    const bool boxed_ok =
        bx.binopv == 1 && bx.loadconstv >= 1 && bx.flstep == 1
       ;

    /* 20) boxed COMPOUND-assign: `s += "x"` -> a CompoundV read-modify-write
     * (num_bin_op in place), not a fallback EvalStmt. */
    VmOpCounts bxc;
    if (!codegen_counts({
            "var s = \"\";",
            "for (var i = 0; i < 5; i++) { s += \"x\"; }",
        }, bxc))
        return false;
    const bool boxed_compound_ok =
        bxc.compoundv == 1 && bxc.loadconstv >= 1 && bxc.flstep == 1
       ;

    /* 21) boxed COMPARISON in a condition: `if (x == 5)` (x dyn) -> a CmpV
     * (the boxed comparison) + a JumpUnlessTrueV branch, no fallback. */
    VmOpCounts bxcmp;
    if (!codegen_counts({
            "var dyn x = 5; x = x + 1; var r = 0;",
            "if (x == 6) { r = 1; }",
        }, bxcmp))
        return false;
    const bool boxed_cmp_ok =
        bxcmp.cmpv == 1 && bxcmp.jutv == 1;

    /* 22) boxed LOGICAL condition: `if (x > 0 && x < 20)` (x dyn) -> two
     * CmpV + a LogV + a JumpUnlessTrueV, no fallback. */
    VmOpCounts bxlog;
    if (!codegen_counts({
            "var dyn x = 5; x = x + 1;",
            "var r = 0; if (x > 0 && x < 20) { r = 1; }",
        }, bxlog))
        return false;
    const bool boxed_log_ok =
        bxlog.cmpv == 2 && bxlog.logv == 1 && bxlog.jutv == 1
       ;

    /* 23) a boxed NON-LOCAL leaf: `s = s + g` where g is a GLOBAL (read by a
     * function, so escaped) -> a LoadGlobalV feeding a BinOpV. */
    VmOpCounts bxg;
    if (!codegen_counts({
            "var g = \"x\"; func rd() { return g; }",
            "var s = \"\"; s = s + g;",
        }, bxg))
        return false;
    const bool boxed_global_ok =
        bxg.loadglobalv == 1 && bxg.binopv == 1;

    /* 24) an INT-valued dict SUBSCRIPT read `d["a"]` (P3): the typed dict read
     * DictLoadInt (a direct dict_present_value map find), NOT the boxed
     * SubscriptV - even though the destination `x` is dyn, the th==i read
     * compiles typed and then boxes. */
    VmOpCounts bxs;
    if (!codegen_counts({
            "var d = {\"a\": 1, \"b\": 2};",
            "var dyn x = d[\"a\"];",
        }, bxs))
        return false;
    const bool boxed_subscript_ok = bxs.dictloadi == 1 && bxs.subscriptv == 0;

    /* 25) an INT-valued dict MEMBER read `d.a` (P3): DictLoadInt (typed dict
     * fast path), NOT the boxed MemberV. This is the 25_dict_member win. */
    VmOpCounts bxm;
    if (!codegen_counts({
            "var d = {\"a\": 1, \"b\": 2};",
            "var dyn x = d.a;",
        }, bxm))
        return false;
    const bool boxed_member_ok = bxm.dictloadi == 1 && bxm.memberv == 0;

    /* 26) a native foreach over a flat int array: the counted loop reads the
     * length once (ArrLen), each element via LoadElemInt, and advances with the
     * fused ForLoopStep - no EvalStmt for the loop itself (the `s = s + x` body
     * is a native IntBin). */
    VmOpCounts fe;
    if (!codegen_counts({
            "var a = [1, 2, 3];",
            "var s = 0;",
            "foreach (var x in a) s = s + x;",
        }, fe))
        return false;
    /* the foreach accumulate tail fuses too (#9 IntAddStep) */
    const bool foreach_ok = fe.arrlen == 1 && fe.loadei == 1
        && fe.iaddstep == 1 && fe.flstep == 0;

    /* 27) a native user-function call: a large (non-inlined) function called in
     * a loop with a non-const int arg lowers to a CallV, not an EvalStmt
     * fallback (the loop var instantiates the template with int, so
     * the body's locals are int - no mandatory-dyn error). */
    VmOpCounts cv;
    if (!codegen_counts({
            "func big(x) { var a=x*2; var b=a*3; var c=b*4; var d=c*5;",
            "              var e=d*6; var f=e*7; var g=f*8;",
            "              return a+b+c+d+e+f+g; }",
            "var s = 0;",
            "for (var i = 0; i < 4; i = i + 1) s = s + big(i);",
        }, cv))
        return false;
    const bool callv_ok = cv.callv == 1;

    /* 28) a migrated read-only builtin (value ABI) -> CallBuiltinV, not a
     * fallback (`sum(a)` has no dedicated lowering). `len(a)` on a proven
     * array lowers PAST the marshal to ArrLen (lever 4b). */
    VmOpCounts cbv;
    if (!codegen_counts({
            "var a = [1, 2, 3];",
            "var dyn x = sum(a);",
            "var y = len(a);",
        }, cbv))
        return false;
    const bool callbuiltinv_ok = cbv.callbuiltinv == 1 && cbv.arrlen == 1;

    /* 29) a MUTATING builtin over a slotted-identifier target (`append(a, x)`)
     * -> CallBuiltinLV (the lvalue ABI), not the EvalStmt fallback. */
    VmOpCounts clv;
    if (!codegen_counts({
            "var a = [1, 2, 3];",
            "append(a, 4);",
        }, clv))
        return false;
    /* The `var a = [1,2,3]` decl now materializes natively (LoadLiteralObjV);
     * the append becomes CallBuiltinLV. */
    const bool callbuiltinlv_ok = clv.callbuiltinlv == 1;

    /* 30) a loop condition with a BOOL VARIABLE (`while (flag && j < N)`)
     * compiles the bool conjunct to a boxed truthiness branch (JumpUnlessTrueV)
     * with NO eval.stmt - it used to bail the WHOLE loop to a fallback. `flag`
     * is a genuine runtime bool (reassigned each outer iter), so it can't fold. */
    VmOpCounts bvc;
    if (!codegen_counts({
            "var flag = false; var j = 0; var s = 0; var i = 0;",
            "while (i < 4) { flag = i % 2 == 0;"
                " while (flag && j < 3) { s += j; j += 1; } i += 1; }",
        }, bvc))
        return false;
    const bool bool_cond_ok = bvc.jutv >= 1;

    /* 31) a for-loop whose init reads a VARIABLE (`for (var k = i; ...)`)
     * compiles the init via a boxed move (MoveV), NOT an eval.stmt - the raw
     * int-store path rejects a bare identifier rhs (it can't prove int-not-bool
     * for a raw store, but a boxed move preserves the real type). */
    VmOpCounts vif;
    if (!codegen_counts({
            "var s = 0;",
            "for (var i = 0; i < 4; i++)"
                " for (var k = i; k < 4; k++) s += k;",
        }, vif))
        return false;
    const bool var_init_ok = vif.movev >= 1;

    /* 32) a const-folded `if (true) { ... }` inside a loop leaves a bare nested
     * block `{ ... }`; the loop-body compiler compiles a scope-free bare block
     * IN PLACE (it used to bail the whole loop to one EvalStmt). `1 < 2` folds
     * to true, so the if drops but keeps its braced body. (Found by the
     * tests/nested_fuzz.py differential fuzzer.) */
    VmOpCounts blk;
    if (!codegen_counts({
            "var s = 0;",
            "for (var r = 0; r < 3; r++)"
                " { if (1 < 2) { s = s + 1; s = s * 2; } }",
        }, blk))
        return false;
    const bool block_ok = blk.intbin >= 2;

    /* 33) a DICT MEMBER store `d.k = v` compiles to a DictStore (like `d["k"]`),
     * the member name a string key - not an EvalStmt fallback. */
    VmOpCounts dms;
    if (!codegen_counts({
            "var d = {\"x\": 0, \"y\": 0};",
            "for (var i = 0; i < 3; i++) { d.x = d.x + i; }",
        }, dms))
        return false;
    const bool dict_member_ok = dms.dictstore >= 1;

    /* 34) a STRUCT field store `s.f = v` / `s.f OP= v` compiles to StoreMemberV
     * (a POD field: coerce + byte store), not an EvalStmt fallback. */
    VmOpCounts sms;
    if (!codegen_counts({
            "struct P { int x; int y; }",
            "var p = P(0, 0);",
            "for (var i = 0; i < 3; i++) { p.x += i; p.y = p.x * 2; }",
        }, sms))
        return false;
    const bool struct_member_ok =
        sms.storememberv >= 2;

    /* 35) a NESTED store `a[i][j] = v` / `a[i][j] OP= v` (matrix) compiles to
     * StoreElem2V (two-level lvalue), not an EvalStmt fallback. */
    VmOpCounts n2;
    if (!codegen_counts({
            "var m = [[0, 0], [0, 0]];",
            "for (var i = 0; i < 2; i++) {"
                " for (var j = 0; j < 2; j++) { m[i][j] = i + j; } }",
        }, n2))
        return false;
    const bool nested_store_ok = n2.storeelem2 >= 1;

    /* 36) a GLOBAL array-base store `a[i]=v` (a top-level array a function
     * reads is a global slot, not a main-frame local) compiles native - a
     * StoreElemInt (base kind rides in in.target), NOT an EvalStmt. */
    VmOpCounts gs;
    if (!codegen_counts({
            "var a = [0, 0, 0];",
            "func use() { return a[0]; }",   /* makes `a` a global */
            "for (var i = 0; i < 3; i++) { a[i] = i * 2; }",
        }, gs))
        return false;
    const bool global_store_ok = gs.storei >= 1;

    /* 37) a DYN / unproven-base store `d[i]=v` compiles to the UNIVERSAL
     * StoreElemValue (vm_subscript_store dispatches flat/general/dict at
     * runtime), NOT an EvalStmt fallback. */
    VmOpCounts uv;
    if (!codegen_counts({
            "var dyn d = [1, 2, 3];",
            "for (var i = 0; i < 3; i++) { d[i] = i * 2; }",
        }, uv))
        return false;
    const bool universal_store_ok = uv.storeev >= 1;

    /* 38) a try/catch region (P8 Inc 0) lowers natively: PushHandler +
     * the enclosing counted loop stays native (for.step); the `throw`
     * inside is a native Throw op (P8 Inc 1). #78 step D: there is NO
     * CatchTest any more - the clause list lives in Chunk::handler_sites
     * and the raise path matches against it directly (the table's CONTENT
     * is pinned by the `vm: handler table` test). */
    VmOpCounts tc;
    if (!codegen_counts({
            "struct E { int v; }",
            "var c = 0;",
            "for (var i = 0; i < 5; i++) {",
            "  try { throw E(i); } catch (E) { c++; } }",
        }, tc))
        return false;
    /* P8 Inc 1: the `throw` is now a native Throw op (not an EvalStmt); the
     * whole try/catch loop has ZERO fallback. */
    const bool try_native_ok =
        tc.pushhandler == 1 && tc.flstep == 1 && tc.throwop == 1
        && tc.handler_sites == 1 && tc.handler_clauses == 1;

    /* P8 Inc 2b: try/finally lowers natively - a handler region + SetPend on
     * each exit + one EndFinally, zero fallback. #78 step D: the "no clause
     * matched" exit (SetPend(reraise) + Jump Lfin) is GONE from the
     * bytecode - vm_dispatch_exc parks the reraise and resumes at the
     * table's fin_pc itself - so the plain shape now has ONE SetPend. */
    VmOpCounts tf;
    if (!codegen_counts({
            "var c = 0;",
            "for (var i = 0; i < 5; i++) {",
            "  try { c += 1; } finally { c += 2; } }",
        }, tf))
        return false;
    const bool try_finally_native_ok =
        tf.pushhandler == 1 && tf.endfinally == 1 && tf.setpend == 1
       ;

    /* P8 Inc 2c: a `return` crossing a finally is native - it INLINES the
     * finally at the return site (it does not set a pend of its own),
     * then ReturnV; ZERO
     * fallback (a fallback EvalStmt-return would skip the finally). Compiled as
     * a function body (codegen_program only covers main). */
    VmOpCounts fr;
    if (!codegen_func_counts({
            "func f(int n) {",
            "  var s = 0;",
            "  try { s = n * 2; return s; } finally { s = 999; }",
            "}",
        }, fr))
        return false;
    /* ZERO SetPend: the try body always returns (the return INLINES its
     * finally), so the normal fall-out path (try.pop + set.pend normal +
     * jmp) is unreachable and the peephole deletes it - and #78 step D
     * removed the handler entry's `set.pend reraise` (the dispatch parks
     * the reraise itself). Only the shared finally block remains, reached
     * from the handler table's fin_pc. */
    const bool ret_finally_native_ok =
        fr.pushhandler == 1 && fr.endfinally == 1 && fr.setpend == 0
       ;

    /* A `break` crossing a finally likewise INLINES the finally at the break
     * site + jumps to the loop exit. The finally `s += 100` is an IntBin,
     * emitted TWICE (inline at the break + the shared block) atop the body's
     * `s += i` - so intbin >= 3 proves the inline. ZERO fallback. */
    VmOpCounts bf;
    if (!codegen_func_counts({
            "func f {",
            "  var s = 0;",
            "  for (var i = 0; i < 5; i++) {",
            "    try { if (i == 2) { break; } s += i; }",
            "    finally { s += 100; }",
            "  }",
            "  return s;",
            "}",
        }, bf))
        return false;
    /* ONE SetPend (#78 step D): the normal try exit's. The "no clause
     * matched" reraise exit is gone; the break INLINES the finally rather
     * than setting a pend. */
    const bool break_finally_native_ok =
        bf.pushhandler == 1 && bf.endfinally == 1 && bf.setpend == 1
        && bf.intbin >= 3;

    /* Chaining: a return crossing TWO nested finallys is native - each is
     * inlined at the return (innermost first), so ZERO fallback. Two trys ->
     * pushhandler==2 + two shared finallys endfinally==2. */
    VmOpCounts cf;
    if (!codegen_func_counts({
            "func f(int n) {",
            "  var s = 0;",
            "  try { try { s = n; return s; }",
            "    finally { s = s + 1; } }",
            "  finally { s = s + 2; }",
            "  return -1;",
            "}",
        }, cf))
        return false;
    const bool chain_finally_native_ok =
        cf.pushhandler == 2 && cf.endfinally == 2;

    /* boxed UNARY `!` in a condition: `if (!x)` (x dyn) -> a UnaryV (the
     * boxed unary) feeding a JumpUnlessTrueV branch, no fallback. */
    VmOpCounts un;
    if (!codegen_counts({
            "var dyn x = \"hi\"; x = x + \"!\";",
            "var r = 0; if (!x) { r = 1; }",
        }, un))
        return false;
    const bool unary_cond_ok =
        un.unaryv == 1 && un.jutv == 1;

    /* boxed unary `!` in a value position: `var b = !x` (x dyn) -> a UnaryV
     * + a MoveV, no fallback. */
    VmOpCounts unv;
    if (!codegen_counts({
            "var dyn x = \"hi\"; x = x + \"!\";",
            "var b = !x;",
        }, unv))
        return false;
    const bool unary_val_ok = unv.unaryv == 1;

    /* defined(param)/defined(local) fold to a literal at resolve time -> the
     * function body has NO fallback for the AST-builtin call (the fold-gap
     * fix that keeps AST builtins out of codegen). */
    VmOpCounts df;
    if (!codegen_func_counts({
            "func f(int p) { var y = p + 1; return defined(p) + defined(y); }",
        }, df))
        return false;
    const bool defined_fold_ok = df.callbuiltinv == 0;

    /* defined(GLOBAL) does NOT fold (execution-order dependent) but is
     * native: a DefinedGlobalV op reading gfuncs->defined[slot]. */
    VmOpCounts dg;
    if (!codegen_func_counts({
            "var gg = 0;",
            "func gt() { return defined(gg); }",
        }, dg))
        return false;
    const bool defined_global_ok =
        dg.definedg == 1 && dg.callbuiltinv == 0;

    /* `a ?? b` in a native body lowers to MoveV + JumpIfNotNoneV (the ??
     * short-circuit) + the rhs into the same dst - no fallback (the old
     * lowering was a node fallback; JumpIfFalse/EvalToSlot are deleted). */
    VmOpCounts co;
    if (!codegen_func_counts({
            "func co(opt dyn v) { var dyn r = v ?? 5; return r; }",
        }, co))
        return false;
    const bool coalesce_ok = co.jinn == 1;

    /* a CHAINED boxed comparison `x == 5 == 1` (a >2-operand
     * MultiOpConstruct) lowers to two CmpV, left-to-right - no fallback. */
    VmOpCounts ch;
    if (!codegen_counts({
            "var dyn x = 5; x = x + 1;",
            "var dyn r = x == 5 == 1;",
        }, ch))
        return false;
    const bool chained_cmp_ok = ch.cmpv == 2;

    /* an ASSIGNMENT used as an expression `a = (b = a + 1) + 2` lowers
     * native (the inner store writes b's slot, the outer reads it). */
    VmOpCounts ax;
    if (!codegen_counts({
            "var dyn a = 0; var dyn b = 0;",
            "a = (b = a + 1) + 2;",
        }, ax))
        return false;
    const bool assign_expr_ok = ax.binopv == 2;

    /* a TYPED IdList reassign `fa, fb = [1, 2]` (float targets - the
     * literal-eliding path declines a coerced target) is a MultiUnpackV
     * with per-target coerce from the unpack_coerce pool - no fallback. */
    VmOpCounts mu;
    if (!codegen_counts({
            "float fa = 0.0; float fb = 0.0;",
            "fa, fb = [1, 2];",
        }, mu))
        return false;
    const bool typed_unpack_ok = mu.munpack == 1;

    /* an EXPRESSION body - `func f(..) => expr`, desugared at parse to
     * `{ return expr; }` - COMPILES to a chunk (a ReturnV over the native
     * expr; before the desugar an expr body had NO chunk and tree-walked
     * under -vm). The tree-walker still runs it via the func_expr_body
     * direct-eval fast path. */
    VmOpCounts eb;
    if (!codegen_func_counts({
            "func inc1(int x) => x + 1;",
            "var dyn keep = inc1;",   /* value-used: the body must be real */
        }, eb))
        return false;
    const bool expr_body_chunk_ok = eb.retv == 1;

    /* an impure-index inc-dec VALUE (`a[f()]++` in an expression) lowers
     * to ONE IncDecChainV (the key temp evaluated once) - no fallback. */
    VmOpCounts idc;
    if (!codegen_counts({
            "var a = [1, 2, 3]; var j = 0;",
            "func f() { j += 1; return j - 1; }",
            "var y = a[f()]++;",
        }, idc))
        return false;
    const bool incdec_chain_ok = idc.idchain == 1;

    return native_ok && fallback_ok && fallback_net_ok
        && nested_ok && bool_safe
        && float_ok && mixed_ok && for_ok && decl_ok
        && read_int_ok && read_flt_ok && write_int_ok && write_flt_ok
        && nested_native_ok && compound_store_ok && read_2d_ok
        && builtin_dispatch_ok && mathfn_ok && peephole_ok
        && array_build_ok && general_for_ok
        && break_cont_ok && compound_cond_ok && boxed_ok
        && boxed_compound_ok && boxed_cmp_ok && boxed_log_ok
        && boxed_global_ok && boxed_subscript_ok && boxed_member_ok
        && foreach_ok && callv_ok && callbuiltinv_ok && callbuiltinlv_ok
        && bool_cond_ok && var_init_ok && block_ok && dict_member_ok
        && struct_member_ok && nested_store_ok && global_store_ok
        && universal_store_ok && try_native_ok && try_finally_native_ok
        && ret_finally_native_ok && break_finally_native_ok
        && chain_finally_native_ok && unary_cond_ok && unary_val_ok
        && defined_fold_ok && defined_global_ok && coalesce_ok
        && chained_cmp_ok && assign_expr_ok && typed_unpack_ok
        && incdec_chain_ok && expr_body_chunk_ok;
}

/* The bytecode disassembler (-vd) renders a native int loop as smart assembly:
 * the fused for.step counter, the register i.bin ops, the fused compare/branch,
 * and a native builtin call (`print(s)` -> call.blt.v via the value ABI).
 * The JIT is disabled here: this pins how the disassembler RENDERS these ops,
 * and with the JIT on approach A deletes a fully-native loop's ops from the
 * bytecode (they move into the fragment - -vdj shows them, not -vd). */
static bool vm_disasm_shape()
{
    std::string src;
    std::vector<Tok> toks;
    for (const char *l : { "var s = 0;",
                           "for (var i = 0; i < 10; i++) s += i*i;",
                           "print(s);" }) {
        if (!src.empty())
            src += '\n';
        src += l;
    }
    lexer(src, 1, toks);
    const bool jit_was = g_jit_enabled;
    g_jit_enabled = false;
    bool ok = false;
    try {
        ParseContext pc(TokenStream(toks), true);
        unique_ptr<Construct> root = pBlock(pc);
        mark_implicit_globals(root.get(), {});
        infer_types(root.get());
        resolve_names(root.get());
        specialize_types(root.get());
        const Block *b = dynamic_cast<const Block *>(root.get());
        if (b) {
            const std::string d = disassemble(codegen_program(b), "main");
            /* the accumulate-for's add+step fuse to the #9 IntAddStep */
            ok = d.find("i.addstep") != std::string::npos
                && d.find("i.bin") != std::string::npos
                && d.find("i.jmp.ifnot") != std::string::npos
                && d.find("call.blt.v") != std::string::npos  /* print native */
                && d.find("halt") != std::string::npos;
        }
    } catch (...) {
        ok = false;
    }
    g_jit_enabled = jit_was;
    return ok;
}

/* #55 STEP 2: -vd/-vdj are FAITHFUL to execution's native CALLS. A function->
 * function call to a native_leaf runs as a native call, so the CALLER's chunk
 * shows `enter.nat` at the call site (the interpreted call.v is kept, dead).
 * disassemble_program replicates the precompile's two-pass + JitCtx to produce
 * exactly that (a per-function codegen+jit with no JitCtx would show a plain
 * interpreted call.v). runtime() keeps the arg non-const (no const-fold). */
static bool vm_disasm_native_call()
{
#if ML_JIT_SUPPORTED
    if (!g_jit_enabled)
        return true;   /* JIT off: no native call to show */
    std::string src;
    std::vector<Tok> toks;
    for (const char *l : {
            "func nl(int a, int b) {",
            "  var t = a * b; var u = t + a; var v = u - b;",
            "  var w = v * a; var x = w + b; return x - a;",
            "}",
            "func nc(int n) {",
            "  var acc = 0;",
            "  for (var i = 1; i <= n; i++) acc = acc + nl(i, n);",
            "  return acc;",
            "}",
            "print(nc(runtime(50)));" }) {
        if (!src.empty())
            src += '\n';
        src += l;
    }
    lexer(src, 1, toks);
    bool ok = false;
    try {
        ParseContext pc(TokenStream(toks), true);
        unique_ptr<Construct> root = pBlock(pc);
        mark_implicit_globals(root.get(), {});
        infer_types(root.get(), true);
        run_optimizers(root.get());
        const Block *b = dynamic_cast<const Block *>(root.get());
        if (b) {
            const std::string d = disassemble_program(b);
            /* nc's OWN section: the native call shows as enter.nat and -
             * #56 step 4 - the interpreted call.v is DELETED (the sync
             * call's every decline conveys/switches; the post-call resume
             * stub is a second enter.nat). */
            const size_t p = d.find("; ===== func nc");
            if (p != std::string::npos) {
                const size_t e = d.find("; =====", p + 20);
                const std::string sec = d.substr(
                    p, e == std::string::npos ? std::string::npos : e - p);
                ok = sec.find("enter.nat") != std::string::npos
                    && sec.find("call.v") == std::string::npos;
            }
        }
    } catch (...) {
        ok = false;
    }
    return ok;
#else
    return true;
#endif
}

/* plans/model-flip.md M1: -vd surfaces the CONTAINER PLAN - how a body
 * partitions into native/island segments and whether it could be ONE native
 * container. A chunk with a still-boxed op is MIXED -> "NOT ready" + the
 * blocking island(s) (here `main`, whose island is a CallV - calls are M5
 * territory, off the nativize-ops path, so this case stays stable); a body whose
 * every op is native-ELIGIBLE -> "READY" (the flip would nativize it), which
 * covers the dict-building foreach `wc`. The tiny arith `add` graduated past
 * READY entirely: with MIN_RUN removed its 2-op body is a NATIVE_LEAF (one
 * call-able fragment, interpreted ops deleted), asserted below.
 * DUMP-ONLY; no emission consumes it yet. */
static bool vm_disasm_container_plan()
{
#if ML_JIT_SUPPORTED
    if (!g_jit_enabled)
        return true;   /* JIT off: no container plan emitted */
    std::string src;
    std::vector<Tok> toks;
    for (const char *l : {
            "func add(int a, int b) => a + b;",
            "func wc(words) {",
            "  var d = {};",
            "  foreach (w in words) d[w] = 1;",
            "  return d;",
            "}",
            "var dyn dcf = len;",
            "dcf([runtime(1), 2]);",
            "print(add(runtime(2), 3));",
            "print(wc([\"a\"]));" }) {
        if (!src.empty())
            src += '\n';
        src += l;
    }
    lexer(src, 1, toks);
    bool ok = false;
    auto section = [](const std::string &d, const char *hdr) -> std::string {
        const size_t p = d.find(hdr);
        if (p == std::string::npos)
            return "";
        const size_t e = d.find("; =====", p + 20);
        return d.substr(p, e == std::string::npos ? std::string::npos : e - p);
    };
    try {
        ParseContext pc(TokenStream(toks), true);
        unique_ptr<Construct> root = pBlock(pc);
        mark_implicit_globals(root.get(), {});
        infer_types(root.get(), true);
        run_optimizers(root.get());
        const Block *b = dynamic_cast<const Block *>(root.get());
        if (b) {
            const std::string d = disassemble_program(b);
            /* main: with the dyn-callee pair nativized (the LAST formerly
             * boxed sequential ops), every op in main is native-eligible -
             * the container plan is READY and NO island line exists. The
             * island-source hop chain (SliceV -> ... -> map/filter -> the
             * dyn call) is EXHAUSTED; a NOT-ready plan reappearing here
             * means a new un-nativizable op entered real code. */
            const std::string mn = section(d, "; ===== main");
            const bool mixed_ok =
                mn.find("container plan: READY") != std::string::npos
                && mn.find("island [pc") == std::string::npos;
            /* add: with MIN_RUN removed (2026-07-25) its 2-op body forms a
             * run, becomes a NATIVE_LEAF (whole body -> one call-able
             * fragment, #55) and its interpreted ops are DELETED - so the
             * section shows the native_leaf line + a single enter.nat
             * instead of a container-plan READY line. (Before, it was
             * "READY but no fragment" - fully native-eligible yet below
             * the run floor, so the native code never ran.) */
            const std::string add = section(d, "; ===== func add");
            const bool add_ok =
                add.find("native_leaf: whole body") != std::string::npos
                && add.find("enter.nat") != std::string::npos;
            /* wc: the dict-building foreach body is fully native-eligible now. */
            const std::string wc = section(d, "; ===== func wc");
            const bool wc_ok =
                wc.find("container plan: READY") != std::string::npos;
            ok = mixed_ok && add_ok && wc_ok;
        }
    } catch (...) {
        ok = false;
    }
    return ok;
#else
    return true;
#endif
}

/* -vd (disassemble_program) dumps 100% of the SERIALIZABLE image, not just the
 * code of funcs: the program's custom TYPES (struct defs - name, POD layout,
 * field offsets, folded consts) and each chunk's POOLS (consts, catch_types,
 * ...). This is the audit surface for the `.myv` stored-bytecode endgame. */
static bool vm_disasm_full_image()
{
    std::string src;
    std::vector<Tok> toks;
    for (const char *l : {
            "struct Point { int x; int y; const DIM = 2; }",
            "func f(int n) {",
            "  try { return n / n; } catch (DivisionByZeroEx) { return 0; }",
            "}",
            "print(f(5));" }) {
        if (!src.empty())
            src += '\n';
        src += l;
    }
    lexer(src, 1, toks);
    try {
        ParseContext pc(TokenStream(toks), true);
        unique_ptr<Construct> root = pBlock(pc);
        mark_implicit_globals(root.get(), {});
        infer_types(root.get());
        resolve_names(root.get());
        specialize_types(root.get());
        const Block *b = dynamic_cast<const Block *>(root.get());
        if (!b)
            return false;
        const std::string d = disassemble_program(b);
        const auto has = [&](const char *x) {
            return d.find(x) != std::string::npos;
        };
        return has("===== types")        /* the custom-type section */
            && has("struct Point")       /* the struct name */
            && has("[pod")               /* POD layout (size varies by arch) */
            && has("int x @0")           /* a field's byte offset (portable) */
            && has("const DIM = 2")      /* a folded struct const */
            && has("catch_types")        /* a chunk pool section */
            && has("DivisionByZeroEx");  /* the catch type name */
    } catch (...) {
        return false;
    }
}

/* highlight_disasm colors each token class of a plain disassembly (256-color,
 * TTY only) AND leaves the text intact - stripping every ESC..m sequence gives
 * the plain input back exactly. */
static bool disasm_highlight_shape()
{
    const std::string plain =
        "; ===== main  (2 instr) =====\n"
        "   0  i.bin        s = r2 + 1\n"
        "   1  i.jmp.ifnot  i < 3, L4\n";
    const std::string c = highlight_disasm(plain);

    const bool colored =
        c.find("\033[1;38;5;222m; =====") != std::string::npos      /* header */
        && c.find("\033[38;5;69mi.bin") != std::string::npos        /* arith */
        && c.find("\033[38;5;214mi.jmp.ifnot") != std::string::npos /* ctrl */
        && c.find("\033[38;5;150m1") != std::string::npos           /* immed. */
        && c.find("\033[38;5;213mL4") != std::string::npos          /* label */
        && c.find("\033[38;5;81ms") != std::string::npos            /* VAR   */
        && c.find("\033[38;5;244mr2") != std::string::npos;         /* reg   */

    std::string stripped;
    for (size_t i = 0; i < c.size(); ) {
        if (c[i] == '\033') {              /* skip an ESC [ ... m sequence */
            while (i < c.size() && c[i] != 'm')
                i++;
            if (i < c.size())
                i++;
        } else {
            stripped += c[i++];
        }
    }
    return colored && stripped == plain;
}

/* The disassembler (a) finds a CLOSURE body in EXPRESSION position (a returned
 * lambda - the complete collect_funcs walk), labels it + shows its captures as
 * an anonymous struct with named capture ops, and (b) drops the dead trailing
 * Halt from a function body that ends in a return (codegen_chunk). */
static bool vm_disasm_closure_shape()
{
    std::string src;
    std::vector<Tok> toks;
    for (const char *l : { "func f(x) { return x + 1; }",
                           "func mk(n) { return func [n] { return n; }; }",
                           "print(f(1) + mk(2)());" }) {
        if (!src.empty())
            src += '\n';
        src += l;
    }
    lexer(src, 1, toks);
    try {
        ParseContext pc(TokenStream(toks), true);
        unique_ptr<Construct> root = pBlock(pc);
        mark_implicit_globals(root.get(), {});
        infer_types(root.get());
        resolve_names(root.get());
        specialize_types(root.get());
        const Block *b = dynamic_cast<const Block *>(root.get());
        if (!b)
            return false;

        /* (a) the returned lambda is disassembled with its capture struct.
         * JIT off for the dump: with it on, the 2-op closure body is a
         * native_leaf whose interpreted ops are deleted (no MIN_RUN), so the
         * named `load.capture` op would not be visible - this test asserts
         * the DISASSEMBLER's closure rendering, not the JIT. */
        const bool jit_was = g_jit_enabled;
        g_jit_enabled = false;
        const std::string d = disassemble_program(b);
        g_jit_enabled = jit_was;
        const bool closure_shown =
            d.find("closure#") != std::string::npos
            && d.find("captures (anon struct): { n }") != std::string::npos
            && d.find("load.capture") != std::string::npos;

        /* (b) f's body `{ return x+1; }` ends in ReturnV, so its chunk has NO
         * trailing Halt (dead). */
        const FuncDeclStmt *f = nullptr;
        for (const auto &e : b->elems)
            if (auto *fn = dynamic_cast<const FuncDeclStmt *>(e.get()))
                if (fn->id && fn->id->get_str() == "f") {
                    f = fn;
                    break;
                }
        bool halt_dropped = false;
        if (f && f->body && f->body->is_block()) {
            /* jit=false: this asserts the CODEGEN shape (the dead Halt is
             * dropped) - with the JIT on, the 2-op body is a native_leaf
             * whose interpreted ops are deleted (no MIN_RUN), so code.back()
             * would be the EnterNative, not the ReturnV. */
            Chunk ch = codegen_chunk(
                static_cast<const Block *>(f->body.get()),
                f->desc->frame_size, /*jit=*/false);
            halt_dropped = !ch.code.empty()
                        && ch.code.back().op == OpCode::ReturnV;
        }
        return closure_shown && halt_dropped;
    } catch (...) {
        return false;
    }
}

/*
 * A DEV-ONLY builtin (show()) is reserved in a SCRIPT (a compile-time
 * SyntaxErrorEx) but allowed in a DEV harness (g_dev_builtins_allowed). This
 * can't be a plain check() test - the whole -rt run sets the flag true - so it
 * flips the flag itself and asserts both directions. A user shadow
 * (`func show`) is left alone.
 */
static bool
dev_builtin_reserved_in_script()
{
    auto rejected = [](bool dev_allowed, const char *const *lines,
                       size_t n) -> bool {
        std::string src;
        std::vector<Tok> toks;
        for (size_t i = 0; i < n; i++) {
            if (i)
                src += '\n';
            src += lines[i];
        }
        lexer(src, 1, toks);
        ParseContext pc(TokenStream(toks), true);
        unique_ptr<Construct> root = pBlock(pc);
        mark_implicit_globals(root.get(), {});
        const bool saved = g_dev_builtins_allowed;
        g_dev_builtins_allowed = dev_allowed;
        bool threw = false;
        try {
            infer_types(root.get());
        } catch (const SyntaxErrorEx &) {
            threw = true;
        }
        g_dev_builtins_allowed = saved;
        return threw;
    };

    static const char *call_show[] = {
        "func f(x) => x + 1;",
        "print(show(f));",   /* no var decl: avoids a mandatory-dyn error */
    };
    static const char *user_shadow[] = {
        "func show(x) => x * 2;",   /* the user's own function, not the builtin */
        "var r = show(21);",
    };
    const size_t n1 = sizeof(call_show) / sizeof(call_show[0]);
    const size_t n2 = sizeof(user_shadow) / sizeof(user_shadow[0]);

    /* script (dev off) rejects; dev on allows; a user shadow is never rejected */
    return rejected(false, call_show, n1)
        && !rejected(true, call_show, n1)
        && !rejected(false, user_shadow, n2);
}

/*
 * Fork F1 (maintainer-decided): a LAZY-ARG builtin (defined/isconst/
 * isconstdecl - the argument is a NODE property, never evaluated) cannot be
 * used as a VALUE in a script - only called directly. An indirect (dyn) call
 * could never reproduce the lazy semantics AST-free. The REPL (dev flag on)
 * keeps the indirect form, like show; a user shadow is untouched; the callee
 * position stays legal.
 */
static bool
lazy_builtin_value_use_rejected()
{
    auto rejected = [](bool dev_allowed,
                       std::initializer_list<const char *> lines) -> bool {
        std::string src;
        std::vector<Tok> toks;
        bool first = true;
        for (const char *l : lines) {
            if (!first)
                src += '\n';
            first = false;
            src += l;
        }
        lexer(src, 1, toks);
        ParseContext pc(TokenStream(toks), true);
        unique_ptr<Construct> root = pBlock(pc);
        mark_implicit_globals(root.get(), {});
        const bool saved = g_dev_builtins_allowed;
        g_dev_builtins_allowed = dev_allowed;
        bool threw = false;
        try {
            infer_types(root.get());
        } catch (const SyntaxErrorEx &) {
            threw = true;
        }
        g_dev_builtins_allowed = saved;
        return threw;
    };

    /* value uses: assigned to a dyn, stored in an array, passed as an arg */
    if (!rejected(false, { "var dyn f = defined;" }))
        return false;
    if (!rejected(false, { "var a = [isconst];" }))
        return false;
    if (!rejected(false, { "print(isconstdecl);" }))
        return false;

    /* the callee position stays legal (no reject at this phase) */
    if (rejected(false, { "var a = 1; print(defined(a));" }))
        return false;
    /* the REPL / dev harness allows the value use (its AST is retained) */
    if (rejected(true, { "var dyn f = defined;" }))
        return false;
    /* a user symbol shadowing the name is untouched (isconst is a runtime
     * builtin, so a user func may shadow it) */
    if (rejected(false, { "func isconst(x) => 2;",
                          "var r = isconst(21);" }))
        return false;

    return true;
}

/*
 * The residual AST nodes live in the pc-keyed Chunk::node_table (the indexed
 * ast_nodes pool + the live Instr::node_idx are dropped after codegen by
 * build_node_table). Verify (a) a FULLY-NATIVE chunk has an EMPTY table (the
 * "serializable" signal) + no live node_idx, (b) a value-ABI builtin call is
 * AST-FREE too - it pools its Builtin + arg carets into Chunk::builtin_calls (a
 * serializable pool) and leaves node_table EMPTY, and every node_table entry is
 * non-null.
 */
static bool
ast_node_pool_minimal()
{
    /* `keep` (optional) receives the AST root, so a case that inspects
     * AST-OWNED pool data (an EmplaceSite's StructTypeDef, owned by the
     * StructDeclStmt) can hold the tree alive across the check - exactly the
     * lifetime rule a `.myv` writer must respect. */
    auto compile = [](const std::vector<const char *> &lines, Chunk &out,
                      unique_ptr<Construct> *keep = nullptr) -> bool {
        std::string src;
        std::vector<Tok> toks;
        for (size_t i = 0; i < lines.size(); i++) {
            if (i) src += '\n';
            src += lines[i];
        }
        lexer(src, 1, toks);
        try {
            ParseContext pc(TokenStream(toks), true);
            unique_ptr<Construct> root = pBlock(pc);
            mark_implicit_globals(root.get(), {});
            infer_types(root.get());
            resolve_names(root.get());
            specialize_types(root.get());
            const Block *b = dynamic_cast<const Block *>(root.get());
            if (!b)
                return false;
            out = codegen_program(b);
            if (keep)
                *keep = std::move(root);
        } catch (...) {
            return false;
        }
        return true;
    };

    /* ZERO-AST by construction: the node_table/ast_nodes members are DELETED
     * from Chunk, so the only checkable residue is a live per-Instr node_idx -
     * verify_ast_free (codegen) already asserts none survive; re-check here so
     * the invariant is pinned by a test, not only an assert. */
    auto table_valid = [](const Chunk &ch) -> bool {
        /* (the "no live per-Instr node handle" check is now TYPE-LEVEL:
         * the runtime Instr has no node_idx field at all - B3 stage 2's
         * CgInstr split; verify_ast_free checks the codegen-side handles
         * were consumed.) */
        return true;
    };

    /* (a) a fully-native int loop (no builtins, no fallback) -> EMPTY table */
    Chunk native;
    if (!compile({"var s = 0;",
                  "for (var i = 0; i < 10; i++) s += i * i;",
                  "var out = s;"}, native))
        return false;
    if (!table_valid(native))
        return false;

    /* (b) a value-ABI builtin call (print) is AST-FREE: it pools into
     * builtin_calls, leaves node_table EMPTY. The pooled entry carries the
     * builtin's name (a serializer re-binds from it). */
    Chunk withb;
    if (!compile({"var s = 5;", "print(s);"}, withb))
        return false;
    if (withb.builtin_calls.empty()
        || !table_valid(withb))
        return false;
    if (!withb.builtin_calls[0].name
        || std::string(withb.builtin_calls[0].name->val) != "print")
        return false;

    /* (c) the checked inc-dec ops (dyn element + dyn member) are AST-FREE:
     * their dual carets (+ the member key) pool into incdec_sites, leaving
     * node_table EMPTY (they were node-kept for the two-caret problem). */
    Chunk incdec;
    if (!compile({"func mkd() { var d = {\"a\": 1}; return d; }",
                  "var dyn dd = mkd();",
                  "dd[\"a\"]++;",
                  "dd.a++;"}, incdec))
        return false;
    if (incdec.incdec_sites.size() != 2
        || !table_valid(incdec))
        return false;
    /* the member form carries the key */
    if (!incdec.incdec_sites[1].memUid
        || std::string(incdec.incdec_sites[1].memUid->val) != "a")
        return false;

    /* (e) defined(<non-identifier>) lowers AST-free (arg eval + true; the
     * old lowering was a node fallback). */
    Chunk defd;
    if (!compile({"var a = [10];",
                  "var r = defined(a[0]);"}, defd))
        return false;
    if (!table_valid(defd))
        return false;

    /* (f) the coerces_dyn accumulator store (`s = s + d`, d dyn) lowers
     * AST-free (CoerceNumV; it was an EvalStmt - the last fallback in a
     * plain accumulator body). */
    Chunk coerce;
    if (!compile({"var dyn d = runtime(2);",
                  "var s = 0;",
                  "s = s + d;"}, coerce))
        return false;
    if (!table_valid(coerce))
        return false;

    /* (g) an INDIRECT (dyn-callee) call lowers AST-FREE (F1 step 2): the
     * carets + arg0's lvalue descriptor ride the call_sites pool - it was
     * the LAST non-fallback node-keeping op. */
    Chunk indir;
    if (!compile({"var dyn f = append;",
                  "var a = [1, 2];",
                  "f(a, 3);"}, indir))
        return false;
    if (indir.call_sites.empty()
        || !table_valid(indir))
        return false;
    if (indir.call_sites[0].a0_form != Chunk::CallSite::A0::slot)
        return false;               /* arg0 = the slotted id `a` (by-ref) */

    /* (d) EmplaceStruct (append(struct_arr, Ctor(..))) is AST-FREE: the ctor
     * def + container/field carets pool into emplace_sites, leaving node_table
     * EMPTY (it was the LAST node in bench/'s and samples/'s chunks). The AST
     * is kept alive for the def->name deref (the def is AST-owned). */
    Chunk emp;
    unique_ptr<Construct> emp_root;
    if (!compile({"struct P { int x; int y; }",
                  "var a = [];",
                  "append(a, P(1, 2));"}, emp, &emp_root))
        return false;
    if (emp.emplace_sites.size() != 1
        || !table_valid(emp))
        return false;
    if (!emp.emplace_sites[0].def
        || std::string(emp.emplace_sites[0].def->name->val) != "P"
        || emp.emplace_sites[0].field_locs.size() != 2)
        return false;

    return true;
}

