void run_tests(bool dump_syntax_tree)
{
    size_t pass_count = 0;
    int err_line;

    /* The test harness is a DEV environment (like the REPL): dev-only builtins
     * (show()) are allowed here so the optimizer-introspection tests can use
     * show() to assert on the rendered optimized AST. A script leaves this
     * false, so show() is a compile-time error there. */
    g_dev_builtins_allowed = true;

    g_exec_engine = ExecEngine::TreeWalk;   /* the oracle */

    for (const auto &test : tests) {

        cout << "[ RUN  ] " << test.name << endl;

        err_line = 0;
        if (check(test, err_line, dump_syntax_tree)) {

            cout << "[ PASS ]";
            pass_count++;

        } else {

            dump_test_source(test, err_line);
            cout << "[ FAIL ]";
        }

        cout << endl << endl;
    }

    for (const auto &ec : extra_checks) {

        cout << "[ RUN  ] " << ec.name << endl;

        if (ec.fn()) {

            cout << "[ PASS ]";
            pass_count++;

        } else {

            cout << "[ FAIL ]";
        }

        cout << endl << endl;
    }

    for (const auto &rt : repl_tests) {

        cout << "[ RUN  ] repl: " << rt.name << endl;

        if (run_one_repl_test(rt)) {

            cout << "[ PASS ]";
            pass_count++;

        } else {

            cout << "[ FAIL ]";
        }

        cout << endl << endl;
    }

    const size_t total =
        tests.size() + extra_checks.size() + repl_tests.size();

    cout << "SUMMARY" << endl;
    cout << "===========================================" << endl;
    cout << "Tests passed: " << pass_count << "/" << total << " ";
    cout << (pass_count == total ? "[ PASS ]" : "[ FAIL ]") << endl;

    /*
     * THE 3-WAY DIFFERENTIAL (maintainer-set, 2026-08-02).
     *
     * Rerun the SAME functional `tests` list in every EXECUTION MODE the
     * project ships - not separate test sets, the same list again, so none
     * of these is added to the count above. The three modes are genuinely
     * different implementations of the language and each pair is an oracle
     * for the other:
     *
     *   1. the AST tree-walker      (the reference; has no JIT path at all)
     *   2. the bytecode VM, JIT OFF (pure interpreted bytecode)
     *   3. the bytecode VM, JIT ON  (native code)
     *
     * WHY THE MIDDLE ONE IS NOT OPTIONAL: with only tw-vs-VM, a bug that
     * lives in the JIT and one that lives in the codegen are the same
     * symptom, and a JIT bug that happens to be unobservable in the default
     * corpus is invisible - which is exactly how a disabled branch remap
     * survived 39 commits (plans/bytecode-inliner.md defect 2). Splitting
     * the VM into with- and without-native says WHICH LAYER broke.
     *
     * Mode 3 runs only where the JIT exists (ML_JIT_SUPPORTED - Linux
     * x86-64 today; see jit.h). Everywhere else mode 2 IS what the VM does,
     * so running it twice would prove nothing.
     */
    struct VmMode {
        const char *tag;      /* the per-test line prefix */
        const char *label;    /* the summary line */
        bool jit;
        bool splice;          /* the bytecode inliner (-bi), default OFF */
    };
    /*
     * BOTH SPLICE STATES, because BOTH ship: the bytecode splice went
     * default-ON on 2026-08-02 and `-nbi` turns it off, so each is a
     * configuration a user can run and neither may be the untested one.
     * (Before the flip these were the extra passes; the labels swapped,
     * the coverage did not.)
     *
     * Two passes per splice state, not one: a splice bug can live in the
     * bytecode it PRODUCES - visible with the JIT off - or in how the JIT
     * CONSUMES it, visible only with it on. Those are different layers,
     * and a JIT-only bug that is unobservable in the default corpus is
     * exactly how a disabled branch remap survived 39 commits.
     */
    std::vector<VmMode> modes = {
        { "vm-nbi", "VM, JIT OFF, splice OFF (-nbi)", false, false },
    };
    if (ML_JIT_SUPPORTED)
        modes.push_back(
            { "jit-nbi", "VM, JIT ON, splice OFF (-nbi)", true, false });
    modes.push_back(
        { "vm", "VM, JIT OFF, splice ON", false, true });
    if (ML_JIT_SUPPORTED)
        modes.push_back(
            { "jit", "VM, JIT ON, splice ON (the script DEFAULT)",
              true, true });

    const bool saved_jit = g_jit_enabled;
    const bool saved_bi = g_bc_inline_enabled;
    std::vector<size_t> mode_pass(modes.size(), 0);
    g_exec_engine = ExecEngine::Vm;

    for (size_t m = 0; m < modes.size(); m++) {
        g_jit_enabled = modes[m].jit;
        g_bc_inline_enabled = modes[m].splice;
        for (const auto &test : tests) {

            cout << "[ RUN  ] " << modes[m].tag << ": " << test.name << endl;

            err_line = 0;
            if (check(test, err_line, dump_syntax_tree)) {

                cout << "[ PASS ]";
                mode_pass[m]++;

            } else {

                dump_test_source(test, err_line);
                cout << "[ FAIL ]";
            }

            cout << endl << endl;
        }
    }

    g_jit_enabled = saved_jit;
    g_bc_inline_enabled = saved_bi;
    g_exec_engine = ExecEngine::TreeWalk;

    bool all_modes_ok = true;
    for (size_t m = 0; m < modes.size(); m++) {
        const bool ok = mode_pass[m] == tests.size();
        all_modes_ok = all_modes_ok && ok;
        cout << "Differential (same " << tests.size() << " tests) - "
             << modes[m].label << ": " << mode_pass[m] << "/"
             << tests.size() << " " << (ok ? "[ PASS ]" : "[ FAIL ]")
             << endl;
    }
    if (!ML_JIT_SUPPORTED)
        cout << "  (no JIT on this platform - see ML_JIT_SUPPORTED, jit.h)"
             << endl;

    if (pass_count != total || !all_modes_ok)
        exit(1);

    exit(0);
}

#else

void run_tests(bool)
{
    cout << "Tests NOT compiled in. Build with TESTS=1" << endl;
    exit(1);
}

